INSERT INTO `Tcomments` (`idquestion`, `ref`, `name`, `content`, `time`, `rank`, `seen`) VALUES
(86, NULL, 'יעל', 'ביולוגיה חישובית אני לקחתי בשנה שעברה, מאוד אהבתי, אבל אני אוהבת ביולוגיה. זה קורס באלגוריתמים בתכלס, עם תכנות במטלב. המבחן במועד א היה ממש סבבה, מועד ב לא עביר. בסהכ זה קורס מעניין.', '2013-02-26 15:51:14', 0, 0),
(76, NULL, 'לא ידוע', 'יתרונות:אורן מרצה טוב\nדחייה בהגשת תרגילי הבית\nחסרונות:\nמלא השקעה בתרגילי בית.\nהרצאות כבדות. הרבה חומר תאורטי קשה\nשאלות נכון/לא נכון בבחינה מבלבלות בטירוף\nסבלתי בקורס, מצטער שלקחתי אותו (וקיבלתי ציון גבוה בבחינה הסופית)\nקורס לא כיפי. קל בקלות להירדם בשיעורים\n\nלסיכום - לא ממליץ. תברחו מזה', '2016-07-28 09:54:47', 0, 1),
(75, NULL, 'לא ידוע', 'קורס שהוא התנדבות בקהילה. ההתנדבות היא שעתיים בכל שבוע וסה\"כ יש 12 מפגשים.\nבתי הספר הם באזור חיפה. בשנה שעברה היו כמה בתי ספר כמו בסמת, עירוני א, עירוני ג וכו\nבנוסף נדרש לכתוב מערך שיעור , או משהו יצירתי שיקדם את הפרויקט ויסייע לשנים הבאות.\nהמערך לא רציני וניתן לכתוב אותו ביומיים במקרה הכי גרוע.\nאופציה נחמדה למי שחושב שהוא יכול/יודע להעביר מערכי שיעור קלילים (שאתם בוחרים מתוך מאגר של שיעורים)  ובנוסף זה קורס שבו לא צריך לכתוב קוד או לפתור משוואות ואלגוריתמים רצחניים והכי נחמד שאין מבחן בסוף.\nכן נדרשים יחסי אנוש בקורס וטאקט.\n\nקורס קליל, ללא תרגילי בית, הגשות, מבחן, וכל עוד לא תרביצו לתלמיד במהלך שיעור, יש לכם ציון גבוה (כמו שכולם קיבלו שנה שעברה)', '2016-08-28 09:54:47', 0, 1),
(76, NULL, 'לא ידוע', 'אחד הדברים הכי טובים בקורסים של אורן לדעתי זה עד כמה שיעורי הבית עוזרים להבין ולתרגל את החומר.\nשיעורי הבית יחסית כבדים (לדעתי לוקחים בערך 6 שעות * 5 תרגילים) למי שיודע את החומר. אמנם, אורן ממש עוזר למי שמתקשה עם שאלות ספציפיות.\nהמבחן לא קל, אבל די הוגן עם מבנה זהה למבחני עבר. השאלות נכון/לא נכון מבלבלות אבל זה 10 שאלות שוות בסך הכל 30 נקודות אז זה לא נורא לטעות בכמה.', '2016-09-30 22:00:19', 0, 1),
(41, NULL, 'לא ידוע', 'נמרוד מרצה מעולה. קורס מעניין מאוד. מי שלומד ונוכח בהרצאות כנראה יצליח. מבחן עם חומר פתוח ולכן כדאי להשקיע לאורך הסמסטר בארגון החומר', '2018-03-20 12:52:59', -1, 1),
(43, NULL, 'לא ידוע', 'הקורס די משעמם, משלב נושאים רלוונטיים מהתעשיה אבל הוא לא פרקטי, תרגילי הבית לא תכנותיים. בסופו של דבר המבחן הוא שינון של כל מה שהמרצה אמר בכיתה, בכתב או בעפ. הציונים לא היו טובים והבדיקה היתה לא ברורה, גם גיל לא ממש מעניין.', '2018-06-01 16:37:00', 1, 1),
(62, NULL, 'לא ידוע', 'הקורס מאורגן מאוד עם מערך של מתרגלים מנוסים ומעבדות יישומיות, תנצלו אותם ואל תוותרו לעצמכם! שפת C עוד תחזור אליכם בהמשך :)', '2019-01-30 19:26:10', 1, 1),
(65, NULL, 'לא ידוע', 'לא התחברתי לסגנון של גדי. הרגשתי זלזול, גם בשעות הקבלה וגם בערעורים במבחן.', '2019-03-28 12:05:46', 0, 1),
(42, NULL, 'ליאור', '  הסמינר יחסית נוח, מאוד תיאורטי ודורש התעמקות במאמר. עיקר הציון נקבע לפי רמת הפרזנטציה ועד כמה תצליחו להציג את הנושא בצורה פשוטה. המאמרים הם תיאורטיים לחלוטין ודרושים הבנה באלגוריתמים ומבני נתונים (בסמסטר הזה בעיקר מאמרים על השוואת/התאמת של מחרוזות ועצים). חלק היו מאוד קלים וחלק די קשים, אבל הציון היה די מתאים. גדי דואג להסביר בצורה ברורה מה הדרישות שלו לפרזנטציה, וחשוב להיצמד אליהן (גם לפי אופן ההצגה של המאמר וגם מבחינת המצגת עצמה). יש נוכחות חובה. גדי היה הוגן ונחמד. בסוף הפרזנצטיה נוהג להעביר ביקורת מול כל הכיתה, צריך להיערך לזה. הציון נקבע על ידי המרצה באופן בלעדי (לא כמו בסמינרים אחרים שיש ציון שנקבע עי הכיתה).', '2019-05-14 11:55:00', 2, 1),
(63, NULL, 'לא ידוע', 'אם כתבתם תשובה לא נכונה במבחן תקבלו 0. אבל אם כתבתם משהו נכון אילן יוותר לכם על הרבה מהפורמליזציה.\nאילן אדם טוב ומרצה מעניין. הוא לא מסודר אז זה מאתגר, והשאלות שלו לא קלות.', '2019-07-24 10:59:01', 1, 1),
(14, NULL, 'לא ידוע', 'שי לוקח קורס שאמור להישמע מעניין ואקטואלי, ועושה אותו נורא משעמם, לא מושך ובנאלי. וחבל!', '2020-01-07 12:37:50', 2, 1),
(52, '9507d350e3d66cda33a0e32cf1924b58', 'שרון', 'שעת קבלה זה עניין בעייתי כי מדובר בראש החוג, אך עדיין משתדל לענות על כל השאלות, מרצה מעולה וחביב מאוד!\nאין תרגילי בית :)', '2020-01-15 12:01:02', 1, 1),
(52, NULL, 'לא ידוע', 'לפעמים מוריד את כל הניקוד של שאלה במבחן על טעויות חישוב. לא היו תרגילי בית, לדעתי לא היה מספיק תרגול.', '2020-02-10 12:01:02', 0, 1),
(41, NULL, 'לא ידוע', 'הקורס מחולק לשלושה חלקים - קול, תמונה ו-וידיאו. \nבכל סופו של חלק בקורס יוצא תרגיל בית מסכם על החומר הנלמד שרובו עיוני (כמו המבחן), עם מטלות MATLAB מינוריות. \nכמו כן, לאחר כל הרצאה עולה בוחן מודל קצרצר המהווה סקירה על קצרה מאוד על החומר הנלמד.\\n\\nהמבחן נערך עם חומר פתוח, והוא כולל בתוכו שאלות עיוניות בלבד (והוגנות למדי) ללא שאלות MATLAB.\nאורך המבחן הוא 2.5 שעות, כאשר במבחן ישנם 17-21 עמודים של שאלות המקיפות את כלל החומר הנלמד בקורס.', '2020-02-11 12:52:59', 0, 1),
(51, NULL, 'לא ידוע', 'אור דונקלמן מרצה מעולה, מהטובים ביותר בחוג. הוא דורש הבנה מעמיקה בחומר ורמה גבוהה במבחן. השיעורים מעולים ומעניינים. קורס מעניין, מבחן קשה. תרגילי בית שדורשים השקעה ומחשבה, אבל לא תכנותיים ברובם. משתלם מאוד - המבחן קשה אבל בסוף הציונים מתוקנים בצורה הוגנת.', '2020-02-12 12:33:07', 0, 1),
(43, NULL, 'ליאור', 'אני עשיתי את הקורס של גיל ורניק, גם לא ממש ממליץ, הוא לא כזה קשה אבל גם לא ממש מעניין לדעתי.\nהוא עובר על קונספטים מאוד כלליים כמו Hadoop ודברים כאלו, והוא גם משלבים תכנים יחסית עדכניים, אבל הוא לא מלמד את זה לעומק או ברמה פרקטית שיש לך מה להגיע לראיון עבודה או להתחיל באמת להתעסק בזה. המבחן הוא פתוח ודורש בעיקר לשנן כל מילה שהוא מדבר עליה בע\"פ בשיעור, יש לא מעט חומר והמצגות לא אינפורמטיביות. לפעמים שואל שאלות עמוקות על נושאים איזוטריים או על דברים שבקושי התייחס אליהן בהרצאה. תרגילי בית קלים ולא דורש הרבה השקעה במהלך הסמסטר (דרושה בעיקר נוכחות ויכולת סיכום). הציונים לרוב לא טובים, יש מי שמצליח להוציא בזה ציונים גבוהים אבל הרוב לא.\nמי שלוקח את הקורס הזה שיזהר מלהקליט ולהיתפס, הוא לא מקבל את זה יפה.', '2020-02-12 14:59:00', 2, 1),
(38, '9507d350e3d66cda33a0e32cf1924b58', 'שרון', 'קורס בסיס סופר חשוב, צריך להשקיע ולוודא שמדובר במרצה מובן! יהיו המון ישומים בהמשך וחשוב להצליח בו. המרצה יודע יותר מדי מהחומר ;) קשה להבין בשיעור אבל אם תגיעו לשעות הקבלה איתו הוא ממש נחמד ועוזר.', '2020-02-18 14:50:00', 0, 1),
(5, NULL, 'לא ידוע', 'המרצה מעבירה את החומר בצורה קצת לא מובנת לפעמים אבל בסה\"כ בסדר. חסר בקורס חומר שנלמד באוניברסיטאות אחרות בקורסים מקבילים כמו אלגוריתמים הסתברותיים וכפל מטריצות.\nיש פרק בסוף הקורס על אלגוריתמי קירוב ואלגוריתמים מקוונים שלדעתי ממש לא שייך שם כי מדובר בנושאים שמצריכים קורס משל עצמם, והם באים כאן על חשבון נושאים אחרים יותר קלאסיים לקורס הזה כמו אלה שמוזכרים לעיל.\nביקורת נוספת היא שהמרצה מעבירה את החומר בצורה יחסית לא פורמלית ואז דורשת במבחן רמת פורמליות גבוהה למדי בהוכחות נכונות של אלגוריתמים מוצעים. האי-קונסיסטנטיות הזו עשויה לפגוע משמעותית בציון במועד א.', '2020-02-27 12:13:22', 3, 1),
(64, 'bb1f49b2fdd8850b656ae6605fc14a0f', 'גיא', 'מבחן הוגן- סה\\\"כ 120 נקודות שמהן אפשר לצבור עד 100. כדאי לפתור ולהבין את כל התרגילים מההרצאות, תרגולים ותרגילי הבית, המבחן היה מאוד דומה. ', '2020-03-02 11:24:20', 2, 1),
(67, NULL, 'לא ידוע', 'רונן מעביר את ההצאות בצורה סופר מובנת וברורה, פורמלי מספיק כדי שנבין איך להתעסק עם החומר אבל לא עד כדי כך שאי אפשר לעקוב אחריו. החומר מרתק והקורס עצמו די מקיף בושאי ההסתברות הבסיסיים שנדרשים בשביל הקורסים המתקדמים יותר בתואר.\nמבחן אמריקאי זה מינוס ענק בקורס הזה אצל רונן.', '2020-03-10 12:17:12', 0, 1),
(40, NULL, 'לא ידוע', 'למלכי חשוב מאוד ההשתתפות של סטודנטים בהרצאות, למרות שהיא לא חובה. \nבסימסטר הזה הקורס הועבר בזום לכן הייתה צריכה להתאים את ההרצאות לכך (פעם הייתה נותנת תרגילי כיתה אבל בזום זה היה יותר בעייתי)\nההרצאות לרוב כבדות ומעייפות, הרבה מהן לא קריטיות מדי כדי להצליח בקורס אבל הן מלמדות לא מעט דברים שיהיו חשובים בכל עבודה שנהיה בתחום התוכנה.\nמלכי הייתה מאוד אדיבה, ענתה על שאלות, והסבירה את הדברים כמה שהיה צריך בשעות הקבלה. קורס מומלץ מאוד, בין הקורסים היחידים שיש בהם פרקטיקה בתואר.\nהציון מורכב מ-3 תרגילי בית שיוצרים פרוייקט- תוכנה, שבסופו של דבר מציגים למרצה והמתרגל.\nהתרגילים נכתבים בשפת ג\'אווה ומשתמשים ב-UML כדי לתאר את התכן', '2020-06-02 12:31:06', 0, 1),
(24, NULL, 'שובל', 'הקורס מעניין מאוד. הועבר בזמן סמס זום הראשון.\nנהניתי מכל רגע. שולי היה מאוד הוגן איתנו. נתן לנו לא מעט הטבות.\nביטל את המבחן, כך שהציון התבסס על התרגילים בלבד, ובנוסף עוד כמה הטבות שקשורות בתרגילי הבית (הארכות, הוספת ימי דחיית תרגיל, הקטנת העונש על איחור).\nהערך המוסף של הקורס הזה בעיניי, מעבר לחומר הנלמד המאוד מעניין, היא זה שדרכו לומדים גם פייתון, מה שאנחנו לא פוגשים בתואר כמעט, בטח לא בקורסי חובה. התרגילים בבודדים, ומעניינים בעיניי, אך דורשים השקעה במהלך הסמס, שלחלוטין משתלמת, בסופו של דבר. \nהציונים גבוהים, ובהתאם גם הממוצע. ממליצה בחום! שולי מרצה מצוין!!', '2020-06-05 20:52:00', 2, 1),
(41, NULL, 'תומר', 'היה לנו מאוד קשה להבין את החומר, למרות שהמבחן והתרגילים ברמה נמוכה... בדיעבד אני מבינה שמומלץ *מאוד* לקחת את הקורס במקביל או אחרי קורס עיבוד תמונה, אחרת זה יותר בסגנון של סינית למתחילים...\nהמרצה משתדל להסביר מהבסיס, אבל בפועל קשה מאוד להבין למה הוא מתכוון - ולכן כדאי מאוד להגיע עם בסיס טוב מחגית בעיבוד תמונה.\nעוד מילה על הציונים - במשך שנים הוא שיחזר מבחנים דומים עם חומר פתוח, אז יכולנו לנסות לענות על השאלות לפי מבחני העבר, במועד ב הוא כבר לא שיחזר והציונים כבר לא היו גבוהים, אז אל תבנו על זה.', '2020-06-20 19:21:00', 2, 1),
(15, NULL, 'לא ידוע', 'הקלטות מהמאה הקודמת, לא זמין, מבחן עמוס ולחוץ בזמן שלא קשור לתרגילי הבית.', '2020-07-07 12:28:54', 0, 1),
(1, NULL, 'לא ידוע', 'מומלץ לפתור ולהבין תרגילי בית, שאלות מתרגולים, הרצאות ומבחני עבר- המבחן היה מאוד דומה לשאלות האלה ואפשר לקבל ציון טוב.', '2020-07-14 12:23:14', 0, 1),
(40, NULL, 'מאור', 'קורס מומלץ מאוד, בין הקורסים היחידים שיש בהם פרקטיקה בתואר. למלכי חשוב מאוד ההשתתפות של סטודנטים בהרצאות, למרות שהיא לא חובה. בסימסטר הזה הקורס הועבר בזום לכן הייתה צריכה להתאים את ההרצאות לכך (פעם הייתה נותנת תרגילי כיתה אבל בזום זה היה יותר בעייתי) ההרצאות לרוב כבדות ומעייפות, הרבה מהן לא קריטיות מדי כדי להצליח בקורס אבל הן מלמדות לא מעט דברים שיהיו חשובים בכל עבודה שנהיה בתחום התוכנה. מלכי הייתה מאוד אדיבה, ענתה על שאלות, והסבירה את הדברים כמה שהיה צריך בשעות הקבלה.', '2020-07-18 20:32:00', 2, 1),
(66, NULL, 'לא ידוע', 'נהניתי ללמוד עם אורן. מעביר את החומר בצורה נהדרת ומסביר מצוין, גם בשעות הקבלה אם יש צורך. אחד הקורסים הבסיסיים של מדעי המחשב - אין מה להוסיף.', '2020-07-30 12:11:42', 2, 1),
(68, NULL, 'לא ידוע', 'אחלה מרצה! חברמן כזה. ספציפית בסמסטר הזה בזכות הקורונה הקורס היה טוב מאי פעם - בעיקר המבחן!', '2020-07-30 12:21:46', 0, 1),
(71, NULL, 'לא ידוע', 'חייבים להעביר באוניברסיטה חוק, מרצה שמעביר קורס מתוקשב חייב להעלות את ההרצאות שלו! אני לא משלם למרצה בשביל שישב רגל על רגל סמסטר שלם ולא יעשה כלום חוץ מלכתוב את הבחינה. קורס חובה מיותר לחלוטין, שפות סף ומבוא לחומרה זה בדיוק אותו דבר רק בשפה שונה, חובה להפוך את הקורס לבחירה', '2021-01-13 12:28:54', 0, 1),
(21, '9507d350e3d66cda33a0e32cf1924b58', 'שרון', 'אליאס מרצה פעם ראשונה, וזה קצת הורגש. המתרגלת סיפקה את כל החומר שהיה צריך וההרצאות הרגישו עבורי מיותרות, כי התרגול חזר על עצמו, בצורה יותר ברורה. יש יותר מדי תיאוריה בהרצאות, שלהצלחה בקורס הזה - לא חיונית.', '2021-01-18 13:16:00', 3, 1),
(62, NULL, 'לא ידוע', 'שולי מרצה יוצא מן הכלל. הקורס מעניין מאוד ולא מצריך ידע מקדים בתכנות/מחשבים.', '2021-02-02 10:53:10', 2, 1),
(5, NULL, 'לא ידוע', 'קורס מעניין, המרצה והמתרגל היו מצוינים.', '2021-02-15 12:15:56', 1, 1),
(69, NULL, 'לא ידוע', 'רונן מאוד מסודר ומסביר בכיף, קצת קל מידי לאבד אותו. אל תוותרו לעצמכם כי אחרת תגיעו למצב שאין לכם מושג מה הוא עושה.', '2021-02-16 12:25:50', 0, 1),
(12, '9507d350e3d66cda33a0e32cf1924b58', 'אנונימי', 'לא התחברתי אליו בכלל. מבזבז זמן בשטויות כמו תורת המשחקים במקום להתקדם בחומר. נכנס לקטנות של כל מיני נושאים, דיבר איזה שיעור על קוד הפמן שבכלל לא לקורס הזה וככה לא הספקנו שני נושאים. המבחנים שלו די הזויים, בעיקר הפתרונות שלהם. אני נכשלתי עם אורן ועדיין ממליץ - עדיף עם אורן!', '2021-02-18 16:44:00', -1, 1),
(39, '9507d350e3d66cda33a0e32cf1924b58', 'שרון', 'קורס לא פשוט לשנה א, כמו כל הקורסים. אבל אם לוקחים את כל הכלים והידע שהשתמשנו בו בפרקטיקה, בסיס חזק להמשך ולהבנה של התואר. סופר חיוני למי שרוצה להתעסק בגרפיקה ולא רק. מרצה אחלה, מעביר את הקורס בפעם הראשונה ויודע מעולה את החומר. קצת מיהר אבל כנראה שבצדק, כדי להספיק. לדעתי היה צריך קצת פחות הוכחות והסברים תיאורטיים ויותר דברים בפועל.', '2021-02-18 23:16:00', 0, 1),
(23, NULL, 'אנונימי', 'הקורס הועבר בצורה טובה ומעניינת יחסית ועם הרבה רצון לבוא לקראת בתרגילי בית (שגם בהם היו ציונים טובים)\nהבעיות התחילו בתקופת המבחנים, אי אפשר להאשים את הקורונה במה שקרה במועד - שתי טעויות של המרצה בשאלה אחת ללא מענה מצד המרצה (אחת התגלתה רק אחרי המבחן אחת דווחה כרבע שעה לסוף ההרצאה)\nתגובת החוג הייתה שהטעויות מינוריות ובגלל שהיה ממוצע גבוה מי שנדפק פשוט נדפק ולא נתנו פתרון הולם לסיטואציה\nמעבר לזה, חלוקת נקודות מוזרה על טופס המבחן שכאשר נבדק המבחן בפועל הניקוד היה שונה- גם לכך לא הייתה תגובה מצד המרצה והיא עשתה מה שהיא רוצה\nבגדול הקורס מעניין וקשה לוותר עליו בעיקר כי הוא קדם להרבה קורסים אחרים\nאצל חגית הכתיבה לא מובנת לעיתים והדבר התפרש לדעתי כזילזול, ראוי שמרצה באוניברסיטה יעבור על מה שהוא כתב לפני שהוא מפרסם את זה, אם זה בהודעות, אם זה בפתרון למבחן ואם זה בבדיקה של המבחן', '2021-02-21 16:35:00', 2, 1),
(27, NULL, 'לא ידוע', 'סיבוכיות מעגלים קורס מעניין, אבל קשה מאוד ללמוד אותו בזום', '2021-02-23 12:35:10', 0, 1),
(18, '4af2ed2bb13f0db81c9058ad5de63e8e', 'אנונימי', 'דונקלמן המרצה הכי טוב שהיה לי אי פעם כנראה, המבחנים שלו אמנם קשים אבל מבחינת יכולת הרצאה הוא בערך הכי טוב שאפשר להיות.', '2021-02-23 14:10:00', 3, 1),
(23, NULL, 'אנונימי', 'קורס מעולה. מומלץ. תרגילי הבית דורשים השקעה. חגית מקסימה, ההרצאות בנויות היטב, מסבירה מעולה.', '2021-02-26 20:41:00', 1, 1),
(52, NULL, 'לא ידוע', 'דני אומנם בקיא מאוד בחומר ויודע לענות על כל שאלה, אך מעולם לא לימד אותנו לכתוב תשובה/הוכחה פורמלית.\nהקורס מאוד קשה. אני מרגיש שאם לא הייתי נעזר בחומרים חיצוניים (כגון צנזור) לא הייתי מצליח בקורס. לא ניתנו תרגילי בית או עבודות, כך שלא היה פידבק על מידת הידע או המיומנות שלנו בקורס.', '2021-03-09 11:27:24', 2, 1),
(31, '90e932faebd595054a6882de5b6facff', 'לא ידוע', 'קורס תואר שני, רוב הציון מורכב מתרגילי בית ויש בוחן בעל פה ששווה 20%.\nהתרגילים כבדים מאוד ודורשים הבנה טובה של חבילות ה-++C הנדרשות בקורס שנמצאות בשלד קוד המצורף לכל תרגיל, בנוסף יש צורך בהבנה מעמיקה של אלגברה וחדוא - לא קורס פשוט בכלל אבל מתגמל מבחינת הציון.\nרועי מרצה טוב מאוד, בכל קורס שלו עובדים עם סלאק - ככה ששאלות שואלים רק שם (יכול לקחת לו זמן לענות לפעמים..)\nלפעמים התשובות לא מספקות יותר מדי, אבל בשעות קבלה הוא יענה בהרחבה.', '2021-05-13 03:42:00', 1, 1),
(30, '90e932faebd595054a6882de5b6facff', 'יותם', 'רועי מרצה טוב מאוד, בכל קורס שלו עובדים עם סלאק - ככה ששאלות שואלים רק שם (יכול לקחת לו זמן לענות לפעמים..)\nלפעמים התשובות לא מספקות יותר מדי, אבל בשעות קבלה הוא יענה בהרחבה', '2021-05-14 02:11:00', 1, 1),
(34, '4af2ed2bb13f0db81c9058ad5de63e8e', 'אנונימי', 'הסמינר מאוד מעניין, והמאמרים ברובם יחסית פרקטיים. אור המרצה הכי טוב בחוג, גם בסמינר זה היה ככה', '2021-06-02 15:54:00', 2, 1),
(32, NULL, 'יאיר', 'קורס מאוד מעניין, מתעסק בקשת הנושאים בתחום הראייה הממוחשבת- החל מ-Hough Trasnform ועד רשתות נוירונים\nהציון הורכב מ-3 תרגילי בית גדולים ופרקטיים (ניתן היה לכתוב בפייתון או Matlab), התרגיל האחרון היה בנושא רשתות נוירונים ונעשה שימוש ב-Google Colab; מצד אחד זה עזר לעבוד עם השותף במקביל ולשתף תוצאות בלייב - מצד שני המערכת חינמית עד נקודה מסוימת ואז אי אפשר להריץ את הקוד על ה-GPU בלי לשלם כסף.. יצר קצת בעיות העניין הזה\nסיימון מרצה חדש יחסית שמעביר את הקורס בפעם הראשונה. ניכר שהוא רוצה לבוא ולעזור כמה שאפשר וחשוב לו שאנשים באמת יבינו את החומר.', '2021-06-03 01:42:00', 3, 1),
(36, '0b988a1a7b344141a1c7346ad682af79', 'יהונתן', '  החומר של הקורס נורא קשה, אבל אפשר לעבור אם מתרגלים אותו טוב. המרצה מעולה. מסביר כמה טוב שאפשר את החומר המסובך בקורס, ועוזר בכל שאלה. ', '2021-06-14 14:01:00', -5, 1),
(35, NULL, 'אנונימי', 'סמינר בתחום של ראייה ממוחשבת\nרוב הנושאים מגיעים מהמאמרים בנושאים יחסית עדכניים בתחום (משנת 2015+ פחות או יותר) ומאוד מעניינים\nהקורס עוזר מאוד בהבנה של רשתות נוירונים בתחום של Vision והבנה כללית של למידה עמוקה. ריטה לא הקשתה יותר מדי במהלך ההרצאות, הייתה הוגנת וגם הציונים הגבוהים בהתאם', '2021-06-15 13:44:00', 1, 1),
(25, '4af2ed2bb13f0db81c9058ad5de63e8e', 'אנונימי', 'הקורס מאוד מעניין, אבל הוא ממש לא לכולם, קריפטוגרפיה היא נושא קשה אבל מעניין מאוד. אור היה ויהיה המרצה #1 בחוג, רק מבחינת מבחנים המבחנים שלו די קשים...', '2021-06-18 23:32:00', 3, 1),
(37, NULL, 'דין', 'הקורס עצמו יכל להיות מעניין יותר אם הוא היה פרונטלי ולא מתעסק בגיאומטריה. יורי זה יורי וכל מה שבא עם זה, הוא היה אחלה מרצה, אבל זה שהוא לא ממש הסתדר עם הזום די פגע בקורס', '2021-06-23 00:24:00', 1, 1),
(37, NULL, 'לא ידוע', 'יורי זה יורי וכל מה שבא עם זה, הוא היה אחלה מרצה, אבל זה שהוא לא ממש הסתדר עם הזום די פגע בקורס. הקורס עצמו יכל להיות מעניין יותר אם הוא היה פרונטלי ולא מתעסק בגיאומטריה', '2021-06-23 13:01:57', 0, 1),
(70, NULL, 'לא ידוע', 'לא הייתה סיבה ללכת להרצאות אז אין חוד על אילן (אבל הוא אחלה גבר). קורס קל מאוד. לא ממש מעניין. אין סיבה הגיונית ללכת להרצאה, רק לראות את התרגולים ולהתכונן על מבחני עבר לפני המבחן.', '2021-06-29 12:27:34', -2, 1),
(72, NULL, 'לא ידוע', 'שי מרצה נורא, משעמם ורפטטיבי. המעבדה עמוסה מאוד וחלק ניכר מהזמן הוא להבין מה הוא רוצה, המשימות לא ברורות בעליל. לא יכול להמליץ על הקורס - הרבה עומס, מעט ידע (המון כתיבת קוד אבל מרגיש חסר פואנטה כי לא מדמה שום דבר אמיתי). עם זאת, הציונים גבוהים כי הבדיקה חפיפניקית מאוד, יש גיוון לגבי מה לעשות בקוד כי הוא לא באמת יודע מה הוא רוצה והוא גם לא מעיף ולו חצי מבט על הקוד או הדוח.', '2021-07-06 12:39:00', -1, 1),
(2, NULL, 'לא ידוע', 'אור המרצה הכי משקיע שיש. עונה על שאלות כמו שצריך ומתייחס לכל סטודנט בכבוד. הקורס קשה מאוד. צריך להשקיע כל הסמסטר אחרת יש סבירות גבוהה לכישלון. חשוב לציין שהמבחנים של אור קשים מאוד.', '2021-07-09 11:21:55', 1, 1),
(68, NULL, 'לא ידוע', 'הפך קורס משעמם למרתק. קורס קליל ומעניין ומתרגל מעולה, מתמטיקאי איכותי.', '2021-07-13 12:21:46', 0, 1),
(24, NULL, 'לא ידוע', 'שולי אחד המרצים הטובים בחוג אם לא הטוב ביותר. קורס מצויין, מנוהל היטב ומעניין.\nציונים גבוהים והתחשבות רבה בסטודנטים (בזמני ההגשה ומענה מהיר בפורום)', '2021-07-13 12:49:22', 0, 1),
(24, NULL, 'שגיא', 'קורס מצויין, מנוהל היטב ומעניין. ציונים גבוהים והתחשבות רבה בסטודנטים (בזמני ההגשה ומענה מהיר בפורום). שולי אחד המרצים הטובים בחוג אם לא הטוב ביותר', '2021-07-17 14:23:00', 1, 1),
(6, NULL, 'לא ידוע', 'מזעזע, המתרגלת נעלמה אחרי התרגול האחרון והקורס הועבר בצורה גרועה.', '2021-07-20 12:14:28', 1, 1),
(57, '9507d350e3d66cda33a0e32cf1924b58', 'אנונימי', 'אחלה קורס, שיפור משמעותי לעומת הקורס עם אנה. מבחנים סהכ הוגנים, נוגע בחומר שרלוונטי למדמח, טכני ויש באתר דפי עזר מעולים. אחלה מרצה עם הרצאות מובנות.', '2021-07-28 20:16:39', 3, 1),
(28, 'a0dbf2a762088b4f320be2ba6f4ed5fe', 'דניאל', 'רונן מרצה מדהים ומסודר להפליא. המבחנים שלו הוגנים במיוחד - הוא בעצמו אומר שבונה אותם בצורה שבה כל מי שמקשיב בהרצאות ועובר על החומר יקבל ציון טוב. הגישה שלו היא תראה לי שאתה מבין על מה אתה מדבר ואני לא אחפש אותך על קטנות.', '2021-09-02 14:52:00', 1, 1),
(33, '4af2ed2bb13f0db81c9058ad5de63e8e', 'אנונימי', 'המעבדה לא קלה, היא לא מסוג המעבדות שאפשר להתעורר ברגע האחרון, והיא דורשת עבודה לאורך כל הסמסטר, אבל לפי דעתי שווה לקחת אותה כי מה שעושים שם מעניין(ותמיד אם מסתבכים יש את מי לשאול במעבדה עצמה).', '2021-09-02 15:15:00', 0, 1),
(19, '0c7000efb8f67fdafb958657db35aac2', 'Danny', 'לא יצא לי ללמוד רשתות, אבל אור אחד מהמרצים היותר טובים באוניברסיטה לדעתי. הוא מעביר את החומר בצורה טובה, והוא בכיף מסביר לסטודנטים שבאים בשעות קבלה (או קובעים במייל לשעה אחרת). עדיין, המבחנים שלו קשים, גם אם למדת טוב, אבל הוא תומך בפקטורים.', '2021-09-02 17:22:00', 4, 1),
(17, '0c7000efb8f67fdafb958657db35aac2', 'Danny', 'למידה ממוכנת שיעור מוצלח, אבל מבלבל. לפחות ככה היה עם ריטה', '2021-09-02 21:00:00', 4, 1),
(15, 'ae9abb5d2cfe0f97f41ac2f744924d1d', 'עינת', 'מרצה מזעזע אבל אין לך ברירה כי זה קורס חובה.\nאצלנו למועדי א, ב הספיקו התרגולים (זה היה כתיבת קוד-חשוב להתאמן על זמן). במועד ג היה משהו הזוי שגם מי שראה את ההרצאות לא ממש ידע מה לעשות..', '2021-09-03 01:11:00', 1, 1),
(15, NULL, 'Yanshuly', 'אם מדובר בהרצאות המוקלטות הישנות אז אכן הם רלוונטיות רק לחלק מהתרגילי בית. מודבר בהקלטות ישנות ממש עם טעויות רבות וחומר שלא תמיד תואם את החומר הנוכחי שמתרגלים עליו. -יוסי הוא מהסוג של המרצים שעיקר עניינם הוא בקורסים מתקדמים ובמחקר, ולכן לא משקיעים בקורס החובה. - חלק קטן מהקורס בסופו של דבר כן מעניין וכן רלוונטי למקומות עבודה ולראיונות עבודה (לדוגמא אופטימיזציה של קומפילציה). ולכן בקורס הזה כן יש חשיבות למתרגל טוב, (אצלנו גם זה לא היה לצערי). - התרגילים היו די זוועה אצלנו היה כתיבת קוד בניגוד לכל מוסכמות השפה (java) אז מבחינת תכנות לא תרם יותר מידי. -אצלנו במבחן גם המתרגל וגם יוסי די שיקרו לגבי הקושי ורמת קטנוניות הבדיקה. וכשניתן לנו העת לערער זה היה בפתיחת מחברות ויוסי טען שגם אם נערער הוא לא מתכוון לקבל את זה(הוא אשכרה אמר לנו את זה)ו ומה שבפועל קרה (89 סופי בקורס הזה)', '2021-09-03 12:04:17', 1, 1),
(22, NULL, 'מאור', 'תקשיב לכל מה שאומר ותנסה לא להרדם...\nהעבודות עמוסות ותצטרך להיות ברצף עבודה גבוה.\nאין מבחן סופי אלא בוחן שהוא עושה לך ואתה צריך להיות *מאד* בקיא בחומר', '2021-09-09 03:40:00', 0, 1),
(19, '4bf97739949547728c662116377c69d7', 'פנחס', 'אור מרצה מדהים ומסביר ממש טוב, אורן גם די טוב. בנוגע למבחנים, המבחנים לא קלים בכלל, אור דורש הבנה של החומר בצורה גבוהה. המבחנים של אורן (יחסית לשל אור) יותר קלים.\nשורה תחתונה - אם אתה מחפש קורס בחירה קליל שיביא לך ציון טוב בלי יותר מדי השקעה זה לא הקורס. אם אתה מוכן להשקיע לא מעט זמן בתרגילי בית ולפתור מלא תרגילי הסתברות מתמטיים- זה הקורס שאתה רוצה .', '2021-09-11 17:12:00', 3, 1),
(14, 'c469a76d5d4a33d63dcca64a72deaf0a', 'Farouq', 'בקורס יש פרויקט 45% מגן, אם לא תעשה אותו אז לא שווה לקחת את הקורס. ממליץ מאוד לקחת ולעשות את הפרויקט כי כך תלמד דברים חדשים', '2021-09-13 16:44:00', 2, 1),
(28, 'ae9abb5d2cfe0f97f41ac2f744924d1d', 'עינת', 'מלמד מסודר, מאוד מתמטי וזה לא קל לכולם (אני קצת איבדתי אותו). מבחנים הוגנים.', '2021-09-13 17:11:00', 2, 1),
(16, 'ae9abb5d2cfe0f97f41ac2f744924d1d', 'עינת', 'מלמדת מעולה ומסודר, לא הכי נחמדה במבחנים. בסמסטר הקודם לא הייתה חובת נוכחות בהרצאות בזום, והיא התנקמה יפה.', '2021-09-13 18:06:18', 2, 1),
(14, 'ae9abb5d2cfe0f97f41ac2f744924d1d', 'עינת', ' קשה מאוד שלא להירדם בשיעורים (ועברתי הרבה מרצים!)\n- אין מספיק סיכומים כי אף אחד לא הצליח להחזיק מעמד ער ככ הרבה זמן.\n- אין מבחני עבר.\n- המבחן קטנוני וקשה, מזכיר את מועד ב במערכות הפעלה כשרחל ניסתה לדפוק מבחן בלי תשובות.\n- המרצה מפחד שהוא חס וחלילה יצטרך לכתוב שאלות חדשות, אז כל אחד קיבל שאלות אחרות, והוא לא מוכן לעשות פתיחת מחברות, כדי שחס וחלילה לא נדע מה התשובות..\nאז הוא מקריא לסטודנטים אחד אחד בזום את השאלה ורק את התשובה השגויה, ואתה צריך באותו רגע להתווכח איתו למה התשובה שלך נכונה (בשונה מערעור רגיל שיש לך זמן לחשוב על טיעונים ולבדוק בחומר), והוא לא מוכן לומר מה התשובה הנכונה!!! יש אנשים שאחרי הערעור לא יודעים מה הייתה התשובה, אז אין דרך ללמוד מטעויות.\nהוא נתן פאקטור של 10 נקודות. בערעורים הצליחו לשכנע אותו שהייתה לו טעות, אז הוא שלח מייל שהוא מבטל את הפאקטור כי הציונים לא מספיק נמוכים (הציון הכי הכי גבוה היה 84! ויש מעל ל80 סטודנטים.)', '2021-09-13 21:10:00', 17, 1),
(29, 'ae9abb5d2cfe0f97f41ac2f744924d1d', 'עינת', '  מלמד טוב בעיניי, אבל מבולגן. אדם נחמד.', '2021-09-14 01:10:00', 4, 1),
(27, '0b988a1a7b344141a1c7346ad682af79', 'יהונתן', 'העומס לא היה גדול - שיעור אחד בשבוע עם תרגילי רשות שניתן לסיים תוך כמה שעות. אור מרצה מצוין ומסביר טוב(ובשיעורי הזום הוא גם פרסם סיכומי הרצאות). והמבחן אינו קשה אם מבינים את החומר מכל ההרצאות. המבחן היה בנוי מ 3 שאלות של 20 נק כל אחת, ככה שלמעשה כל סטודנט קיבל 40 נקודות על ההתחלה, והיה חומר פתוח, ובנוסף הוא גם נתן אפשרות לכל מי שהשתתף בהרצאות לעשות עבודה חלופית למבחן. לדעתי מומלץ.', '2021-09-14 14:52:00', 1, 1),
(20, 'ae9abb5d2cfe0f97f41ac2f744924d1d', 'עינת', 'קורס טוב. המרצה מעניין. תרגילי הבית לא עמוסים. מבחן נחמד (תעברו על שיחזור מתקופת הזום ותבינו את החישובים).\nהחיסרון בקורס הזה הוא שיש תרגיל בית של מסחר בבורסה, הציון בו נקבע לפי הרווח שלך, למרות שעוד לא למדת לסחור בבורסה. בכל מקרה, ארי נתן חסם מינימום, ומי שעשה את הכל כנדרש לא יצא עם ציון מתחת ל80 בתרגיל.', '2021-09-14 15:10:00', 3, 1),
(17, '55b498b91554a6a8f521fdcc1eded665', 'אנונימי', 'החומר לא קל וממש תיאורטי ומלא מתמטיקה אבל יפה ומעניין, התרגילים היו מגן ולא כבדים, והמבחן דורש הבנה טובה לחומר למרות שהיא בדרך כלל מבקשת תשובות ללא הסברים..\nולפי דעתי לא ממש כדאי לקחת אותו בלי לקחת קורסים שהוא קדם להם (כמו למידה עמוקה) אבל עדיין מומלץ והתחום מעניין', '2021-09-14 16:56:00', 8, 1),
(17, '90fb693f5e42ddfcab8ac125a0f4373c', 'מיכאל', 'Dan is a new lecturer. The course in last year was relatively easy. Now - it can be changed. But, it is a prerequisite to Deep Learning, and also machine learning is now very popular in industry, so it might be worth learning it anyway', '2021-09-14 16:57:00', 2, 1),
(22, 'c469a76d5d4a33d63dcca64a72deaf0a', 'Farouq', '(נטו תכנות בC++) קורס מאוד מעניין ובו עושים דברים מדהימים ומגניבים. אם יהיה שותף רציני ותעקבו אחרי החומר ולא דוחים את העבודה לדקה 90, יהיה קל לקבל 90+\nהערה:- רועי מאוד נחמד בבדיקת התרגילים.', '2021-09-14 17:12:00', 1, 1),
(16, '55b498b91554a6a8f521fdcc1eded665', 'מעיין', 'אני מסכימה עם מה שאמרה עינת לגבי נגה, שלושת המועדים עם נגה לא היו קלים למרות שאמרה לנו בתחילת הסמסטר המבחן יהיה קל', '2021-09-14 17:32:00', 2, 1),
(20, NULL, 'בסל', 'אני דווקא להפך, הקורס והמרצה יחסית משעממים, אין הרבה מה ללמוד במיוחד בזמן למידה למבחן, אם יש רפרנסים אז זה קצת שונה\nאבל אז בזמנו לפני שנה וחצי היה ממש קשה למצוא מה ללמוד', '2021-09-14 19:12:00', 1, 1),
(25, '90fb693f5e42ddfcab8ac125a0f4373c', 'מיכאל', 'Crypto - is the same idea like all other courses of Orr. Its a course of riddles. If you managed to understand the point and main idea - you will be very close to 90 after a factor. If not - the questions in the exam have many small parts, enough to scratch passing grade. Also HWs are not mandatory, but they have a huge bonus on a final grade. HWs are tough - they all built from exam questions usually.\nThe course itself is very interesting. And Orr is a perfect lecturer. Btw, there are very good video lectures from the past years, they cover 95% of material.', '2021-09-15 00:16:00', 2, 1),
(14, '189a8828aa2275f6c9651774e86494d5', 'אנונימי', '   שי ממש בעייתי, החומר לא הכי מעניין (פשוט מליון אלגוריתמים שונים שצריך לשנן) ושי בעצמו לא מרצה בצורה מעניינת אז זאת חוויה נוראית.\nחוץ מזה המבחן עצמו פשוט כתוב בצורה מביכה עם שאלות בלתי אפשריות (נניח לפחות 10 נקודות מהמבחן זה הימור לא משנה כמה למדת) ויש מעל 1000 שקופיות של חומר שעל כל מילה בכל אחת מהן הוא יכול לכתוב שאלה.\nאצלי במבחן *הוא* טעה ב3 שאלות והייתי צריך להוכיח לו שהוא טועה בערעור בלי לדעת מראש מה הטעויות ובלי לראות אפילו את השאלות (הוא הקריא)\nמה שכן, שי מאוד רוצה לעזור וללמד, הוא תמיד עונה למיילים ומוכן בכיף לקבוע פגישות זום', '2021-09-15 15:00:00', 1, 1),
(26, '0b988a1a7b344141a1c7346ad682af79', 'יהונתן', 'זו מעבדה שהיא 100% על הסטודנט; עדי מביאה מאמר שהיא הייתה חלק מהכותבים שלו והסטודנטים צריכים להבין אותו (קשה אך אפשרי), ואחר כך לממש את האלג שמתוארים בו באופן כמה שיותר טוב. וזה כבר הרבה יותר קשה בגלל שאתה תצטרך להבין לחלוטין בעצמך איך עובדת סכמת הצפנה מורכבת ואחרי כן לממש אותה באופן מוצלח בקוד שלך (מה שרוב הסטודנטים לא הצליחו בו, ופעלו עם הסכמה כמו בקופסה שחורה). עדי לא ממש פעילה במהלך הסמסטר, וזה התבטא בכך שרק בסוף הסמסטר היא הסבירה שצריך לעשות יותר מסתם מימוש פשוט של המאמר אלא גם להוסיף לו משהו משלנו, ורק בסוף הסמסטר היא בדקה את הגשות הביניים שלנו והביאה תיקונים שצריך לעשות - וכל אלה הוסיפו המון לחץ ועבודה בסוף הסמסטר בדיוק בתקופת מבחנים. לא מומלץ כלל.', '2021-09-17 02:28:00', 3, 1),
(13, '9507d350e3d66cda33a0e32cf1924b58', 'שרון', 'עמי הוא מרצה קשוח, הוא מאוד קפדני ודורש לדעת בעל פה משפטים והתנאים אליהם, ללא הוכחה כמובן. גם במבחן - דורש נימוק ולא רק תשובה. אם להשוות לקורס הקיץ - אצל עמי מקבלים יותר ידע והבנה על החומר. ממליץ לא לדחות לקיץ', '2021-09-18 16:30:00', 3, 1),
(11, '9507d350e3d66cda33a0e32cf1924b58', 'אנונימי', 'קורס לא טוב, לא מודרני. נוגע בנקודות לא רלוונטיות בשיט ודברים שלא יתרמו לסטודנט. זה יותר שיעור בהיסטוריה של השושלת הסינית מאשר קורס נורמלי. הדירוג הוא 1 ולא 0 כדי שזה ייספר, כי זה באמת גרוע. הלוואי ויכולתי להגיד לכם ״אל תקחו״. המרצה - עם האף למעלה. האוניברסיטה משלמת למרצה על מנת שתלמד ולא על מנת שתשלח אותנו לראות הקלטות ואז תקיים שעת קבלה מסכנה עם בוחן. מלאת חשיבות עצמית, לא מסכימה להעלות מבחני עבר כי ככל הנראה משחזרת או שיש לה אוסף מוגבל של שאלות. הקורס צריך להתחלף בקורס מודרני ומעניין, להשאיר את הפרטים החשובים, גם אם הם תיאורטיים, אבל שיהיה לי מושג בפועל איך מערכת הפעלה עובדת ואיך אני בונה או מתכנן אחת.', '2021-09-19 00:16:00', 0, 1),
(12, '1e9ed1bfb4da5dac0baf5dc5c97c1baf', 'יונתן', 'גיא מרצה מאוד נחמד אך מעט מבולגן, מעביר את הקורס בצורה נחמדה עם חידות לפני כל הרצאה, מבחנים הוגנים (לדעתי) ותרגילים קשים יותר מהמבחן לאורך הסמסטר. סך הכל לא רע אך מבולגן, צריך לשמור על ריכוז כדי לעקוב אחריו.', '2021-09-20 22:54:00', 2, 1),
(41, 'ae9abb5d2cfe0f97f41ac2f744924d1d', 'עינת', 'מסכימה עם תומר. רמת הקורס הייתה נמוכה ובכל זאת היה לנו קשה להבין את החומר. הקורס עם חגית לא חופף, אבל עדיין נותן רקע מובן יותר. בכל מקרה, נמרוד מרצה נחמד ומשתדל מאוד שיהיה מעניין. ', '2021-09-27 03:47:00', 1, 1),
(23, 'ae9abb5d2cfe0f97f41ac2f744924d1d', 'עינת', 'חגית מרצה מדהימה והקורס מועבר בצורה מסודרת. ממליצה בחום.', '2021-09-27 15:14:00', 0, 1),
(32, 'ae9abb5d2cfe0f97f41ac2f744924d1d', 'עינת', 'הקורס בנוי מ3 תרגילים, ללא מבחן. היה קצת קשה להבין מה לעשות, אבל בסופו של דבר הציונים טובים, המרצה נחמד ומפרגן.', '2021-09-28 01:08:00', 0, 1),
(33, NULL, 'אנונימי', 'מעבדה מעניינת ופרקטית אבל צריך לבוא אליה בגישה הנכונה, יש הרבה דברים שלא תלויים בסטודנט, הרחפנים יכולים לא לעבוד והרבה דברים יכולים להשתבש, חשוב מאוד לעבוד מתחילת הסמסטר על מנת שלא להיכנס ללחץ בגלל הבעיות האלו, גם אם תעשו הכל נכון דברים יכולים לא לעבוד. ', '2021-09-29 13:11:00', 1, 1),
(8, NULL, 'אנונימי', 'קורס מעניין מאוד, אורן מרצה מעולה, אבל זה קורס מאוד קשה ביחס לזה שהוא בחירה של 3 נ\"ז, מי שהתחום מעניין אותו יכול ליהנות מהקורס, אבל זה לא קורס לקחת בשביל 3 נקודות קלות       ', '2021-09-29 15:00:00', 4, 1),
(6, '9507d350e3d66cda33a0e32cf1924b58', 'אנונימי', 'אני עברתי את הקורס אך אני לא יכול להעיד שהבנתי את הקורס. הקורונה והעובדה שהיינו צריכים לראות הרצאות מוקלטות (עם שעת קבלה) זאת לא הסיבה, פשוט תדחו בסמסטר. המתרגלת הייתה מעולה אבל לצערי היא לא כותבת את המבחן.', '2021-09-30 22:56:22', 0, 1),
(10, '189a8828aa2275f6c9651774e86494d5', 'איתן', 'יאיר מלמד מעולה, הבעיה היחידה בקורס שלא באמת מלמדים design patterns, נותנים טעימה מהם ממש בסוף הקורס בלי להסביר באמת למה הם חשובים. במועד  הייתה שאלה לא מנוסחת היטב, שאם השתמשת בdesign pattern קיבלת 100 ואחרת 0, במועד  הוא הבין שזה לא לעניין והיו שאלות רגילות', '2021-10-03 13:14:00', 2, 1),
(5, '189a8828aa2275f6c9651774e86494d5', 'איתן', 'נגה מרצה מעולה, מסבירה כל דבר בצורה טובה ואיטית. מועד  היה טוב והוגן, מועד  היה עם שאלה אחת שלדעתי הייתה הרבה מעבר לרמה שמצופית, יותר מתאימה לתרגיל בית עם שבוע מאשר לחצי שעה במבחן', '2021-10-03 18:26:00', 3, 1),
(13, '189a8828aa2275f6c9651774e86494d5', 'איתן', 'עמי הוא מתמטיקאי, מה זה אומר? שהוא מצפה למתמטיקה אמיתית, כזאת שבה כל מעבר דורש הסבר מפורט, אם השתמשתם במשפט ולא משנה עד כמה טריוויאלי אז כדאי מאוד שתראו שהתנאים שלו התקיימו אחרת הוא לא יקבל את זה. זה אולי לא קל, אבל זה גם לא קשה למי שמשקיע בזה מתחילת הסמסטר, כמו שחדוא בכללי דורשת צורת חשיבה כך גם פתירת תרגילים עבור עמי, ברגע שמתרגלים זה קל. רוב התרגילים שהוא הביא במבחן היו הוגנים עד פשוטים (חוץ מהתרגיל האחרון שגם עליו אפשר בקלות לקבל 10/20), הוא לקח תרגיל אחד מתרגילי הבית', '2021-10-03 19:16:15', 2, 1),
(40, '189a8828aa2275f6c9651774e86494d5', 'איתן', 'קורס חשוב, עבודה פרקטית ומספקת על פרויקט אמיתי. מלכי מאוד מתחשבת ומציעה בונוסים של עד 8 נקודות. מלכי לא אוהבת לתת ציוני קצה, לא גבוהים ולא נמוכים, אז פרויקט נוראי יקבל ציון סביר, ופרויקט מעולה יקבל 95 מה שמאוד מציק, במקרה שלנו היא אפילו נתנה לנו רק 3 נוקודת בונוס מתוך ה8 שהגיעו לנו (עמדנו בתנאים שהיא הציבה לבונוס) רק כדי לא לתת לנו 100', '2021-10-03 21:07:00', 0, 1),
(11, '189a8828aa2275f6c9651774e86494d5', 'איתן', 'הקורס מעניין סך הכל, קונספטים מעניינים לפתרון בעיות, שגם אם הן ישנות עדיין חשובות להבנה למי שיתעסק בנושא. רחל מרצה סבירה, מסבירה סביר אבל יש נושאים מסובכים יחסית שהיא לא הסבירה טוב וזה היה ניכר בשעות הקבלה לקראת המבחן שבהן רוב הסטודנטים לא הבינו דברים פשוטים יחסית. זה נובע גם מכך שהתרגולים בכלל לא קשורים לחומר שרחל מעבירה ולכן גם אין באמת תרגול פרקטי לקראת המבחן. רחל העלתה לנו 3 מבחני עבר, כל אחד מהם היה קל יותר מהמבחן שקילבנו, ולהם היו שעתיים (או שעתיים וחצי) ולנו היו 72 דקות (שבסוף קיבלו הארכה ל90 דקות), כלומר רחל לא יודעת לכתוב מבחנים והיא יכולה להפיל עליכם שאלות נוראיות ולא ברורות. היו לי שלושה ימים ללמוד למועד  ושבועיים למועד , ויתרתי על המועד  כי ידעתי שהציון לא תלוי בי בגלל השאלות שהיא מביאה, אז תיגשו לכל מועד כאילו הוא האחרון שלכם.', '2021-10-04 00:16:00', 2, 1),
(21, '189a8828aa2275f6c9651774e86494d5', 'איתן', 'אני עשיתי הפוך משרון, ראיתי רק את ההרצאות והתרגולים הרגישו לי חסרי פואנטה, אולי רפרנס לעבור עליו מהר אבל לא שווים יותר מ20 דקות השקעה. אליאס לימד בצורה מעולה, יותר טובה מ95% מהמרצים באוניברסיטה. הוא היה מעניין מאוד, הסביר בצורה טובה, וענה על כל השאלות. ההרצאות שלו היו ב8 בבוקר והוקלטו ועדיין הגעתי לרובן שזה כבר אומר הכל.', '2021-10-04 01:01:00', 3, 1),
(4, '0b988a1a7b344141a1c7346ad682af79', 'יהונתן', 'השתתפתי בשיעור הראשון בשנה שעברה ופרשתי- הקורס מועבר באנגלית, עם נוכחות חובה והוא ללא מבחן. יש תרגילים כל שבוע שחובה להגיש, ויש תורנות של הסטודנטים בקורס שכל אחד בתורו צריך לסכם את ההרצאה השבועית ולהגיש לעדי- כל ההגשות צריכות להיות ב LAETX. לפי מה שהבנתי אחרכך כל מי שעמד במשימות האלו קיבל 100.', '2021-10-04 01:14:00', 0, 1),
(9, NULL, 'אנונימי', 'עידן מרצה נחמד מאוד גם בהרצאות, גם בכתיבת המבחן וגם בבדיקה, הבעיה היא שהקורס (או שזה בגלל אופן ההוראה של עידן) משעמם יחסית, בקיץ אחו שתי הרצאות של 3 שעות בשבוע וכל הרצאה מפוצצת במשפטים, מושגים והוכחות. קצת קשה לעקוב. ', '2021-10-04 21:08:11', 1, 1),
(11, NULL, 'אנונימי', 'לא אהבתי את הקורס. יש בו המון המון חומר ואין דף עזר בבחינה, ההרצאות די משעממות ואין כמעט תרגול שדומה למבחן. מה שכן, רחל מאוד מאוד נחמדה ורוצה לעזור, היא מרצה חביבה מאוד. ', '2021-10-09 13:02:00', 0, 1),
(7, NULL, 'אנונימי', 'הפורמט הוא כזה: המרצים (אילן ויורי מעבירים את זה יחד) מפרסמים אוסף של בעיות במגוון תחומים - גרפים, אלגוריתמים, פונקציות בוליאניות, עצי הכרעה, ועוד. בכל שבוע, המשתתפים בסדנה מציגים את פתרונותיהם לבעיות שהם בחרו, והציון הסופי נקבע ע\"י כמה בעיות כל אחד פתר ובאיכות של הפתרונות. החצי או שליש האחרון של כל מפגש מוקדש להרצאה קצרה ולא פורמלית כל כך על נושא שרלוונטי לבעיות שהם פרסמו, ויש שיח על איזה תחומים ייראו בבעיות הבאות. אישית, נהניתי מהקורס, אבל הלחץ לפתור בעיות לפני שאנשים אחרים יספיקו הקשה עליי קצת. מומלץ בחום למי שאוהב/ת תיאוריה, מחפש/ת אתגר, ושאין לו/ה פחד במה.', '2021-10-17 14:04:00', 1, 1),
(27, NULL, 'אור', 'מצטרף למה שיהונתן אמר כאן ואוסיף שהחומר היה סופר מעניין ושהעבודה החלופית שמוצעת לאלה שמשתתפים באופן פעיל בהרצאה יכולה להיות כיפית ביותר - משהו בנוסח סמינר בערך.', '2021-10-17 20:32:00', 1, 1),
(16, NULL, 'אנונימי', 'מרצה טובה באופן כללי, מבחן נוראי, קוטלת על כל פסיק ולא מוכנה לערעורים. לא ממליץ בכלל.', '2021-10-23 23:06:00', 4, 1),
(12, 'e0ad4ca0715745d13b4b3a189a0ef5b2', 'יובל', 'המבחנים היו יחסית הוגנים, אני כן חושב לעומת רבים אחרים שהוא יודע להסביר את החומר בצורה סבירה. אין ספק שהוא לא ניחן ביכולות הוראה יוצאות דופן ויש לו נטייה לסבך דברים אבל אם מקשיבים לו טוב אפשר להבין ואפילו להינות.', '2021-11-27 15:20:00', 0, 1),
(13, 'e0ad4ca0715745d13b4b3a189a0ef5b2', 'יובל', 'דרש המון ידע ודקדקנות, רוב המבחן היה פשוט אבל היה תרגיל שניים מאתגרים יותר שגרמו בערך לכולם לאבד 15-20 נקודות ככה שלזכרוני היה רק אולי אחד מעל 90. מרצה מעולה מבחינת העברת החומר אני מאוד נהניתי גם מאוד אהבתי את רולא המתרגלת ואת תרגילי הבית שהיו הוגנים והכל היה מוסבר היטב. אם עמי היה פחות דקדקן והמבחן היה קצת יותר הוגן, הייתי גם מסיים בציון גבוה ויוצא מבסוט מאוד מהקורס אך לצערי זה לא קרה. הקורס דרש ממני הכי הרבה השקעה מכל הקורסים שעשיתי - אני חושב שהוא שווה ערך לקורס וחצי מבחינת עומס.', '2021-11-27 16:58:00', 0, 1),
(2, 'e0ad4ca0715745d13b4b3a189a0ef5b2', 'יובל', 'מרצה מעולה, מסביר היטב את החומר ומשקיע ומוודא שהסטודנטים מבינים. המתרגלת אצלינו הייתה לא טובה אז נעזרתי בתגבורים של האקדמיה פלוס בשביל להצליח. בעיניי, קורס מאוד מעניין ובהחלט קורס בסיס חשוב להמשך התואר שכדאי להצטיין בו. אני אישית מאוד נהניתי.', '2021-11-27 23:16:00', 0, 1),
(39, 'e0ad4ca0715745d13b4b3a189a0ef5b2', 'יובל', 'מרצה טוב בסך הכל, לפעמים קצת ממהר מדי ולא הכל מועבר בצורה הכי ברורה ומסודרת אבל כן אפשר להבין והחומר של הקורס לא היה יותר מדי קשה וגם המבחן היה הוגן.', '2021-11-27 23:24:00', 0, 1),
(1, '9507d350e3d66cda33a0e32cf1924b58', 'שרון', 'נגה מעולה. היא מדברת בשפה ברורה, היא מובנת לגמרי, היא עונה על כל השאלות ומסבירה ועוזרת. אבל - במבחנים די מורגש שיש כעס כלפי מי שלא מגיע להרצאות (על חשבון מי שכן). תסתכלו על ההיסטוגרמות שלא משנת הקורונה 2020. תשקלו טוב לפני לקיחת קורס איתה.', '2021-12-26 12:43:52', 0, 1),
(44, '9507d350e3d66cda33a0e32cf1924b58', 'אנונימי', 'סיימון קצת איטי, והאמת שזה לטובה. אני צפיתי מהזום וזה בהחלט היה הרבה יותר טוב. הוא מכניס לדעתי יותר מדי חומר והיה צריך ללמד ממוכנת ואינפורמציה בתור העשרה ולא כחלק מהחומר.', '2021-12-26 12:50:31', 0, 1),
(15, '1f39a9aebba36f422ddb0b694c8c8e8d', 'אנונימי', 'הקורס מחולק לארבעה נושאים: יצירת Pcode (דומה למה שעושים בשפות סף), אופטמיזציות, דקדוקים חסרי הקשר ותזמונים (כמו במבוא לחומרה), ותרגילי הבית היו לבנות מהדר (כלומר שלושה תרגילים שנבנים אחד על השנה). סך הכל את רוב החומר שמופיע בבחינה רואים בוריאציה דומה בקורסים אחרים ולכן אני ממליץ באמת לקחת שפות סף וחומרה כדי להתעמק בחומר בקורסים יותר קלים ולבוא עם הרקע הזה למהדרים. הפורמט של הקורס הוא הרצאות מתוקשבות ותרגולים פרונטליים, ההרצאות די מיותרות ברובן. ', '2021-12-30 17:01:12', 0, 1),
(44, 'e0ad4ca0715745d13b4b3a189a0ef5b2', 'יובל', 'אישית אני לא התחברתי, מרצה איטי שלוקח לו הרבה זמן כל פעם להיזכר מה הוא רוצה להגיד אז אני רואה הקלטות שלו ושם על 1.75 מהירות. אישית, מרגיש לי שהוא לא יודע טוב את החומר והוא לא מייצר שום הבנה של החומר בהסברים שלו מה שמאוד קריטי בקורס כמו הסתברות. שורה תחתונה אני חושב שהוא מרצה לא טוב אחד הפחות מוצלחים שהיו לי בתואר אבל נראה שיש לו רצון טוב שזה גם משהו.', '2021-12-31 07:15:35', 0, 1),
(3, '9507d350e3d66cda33a0e32cf1924b58', 'אנונימי', 'אל תאמינו לשמועות. יעל כבר לא בונה את המבחנים, היא לא משחזרת והיא אפילו לא בנתה את המבחן בקיץ האחרון. אז אם אמרו שהתב בקטנה והמבחן קליל - לא. כמו סמסטר רגיל (קל יותר מאצל עמי)', '2021-12-31 11:05:25', 0, 1),
(20, '1f39a9aebba36f422ddb0b694c8c8e8d', 'אנונימי', 'קורס חביב. זז קצת לאט ולא הכי פרקטי בעולם אבל סך הכל נחמד מאוד. ', '2022-01-14 21:47:32', 0, 1),
(8, 'e8c2cf616718e0e8fca3dffeb91ace4f', 'אנונימי', 'אורן מרצה מעולה, הוא מסביר טוב והמבחנים שלו הוגנים, למראת זאת הקורס לא קל וזה חומר ברמה של תואר שני, אני אישית נהניתי מאוד מהמהרצה והחומר,ממליץ על זה למי שאוהב את החומר ומוכן לשבת ולחזור ולהבין את הדברים יותר לעומק לבד כי החומר הוא כזה (מאוד מאוד מעניין אבל קצת קשוח) וחשוב לציין שזה לא \"3 נקודות קלות בקיץ\"', '2022-02-04 20:14:57', 0, 1),
(23, '1fbeaaff0a47b69995db6b8520f69cff', 'שחר', 'קורס מעניין מאוד,גם חגית וגם המתרגל עזמי העבירו את החומר בצורה מעולה. החל מהשנה תרגילי הבית נכתבים בpython כך שהקורס גם פרקטי. ממליצה מאוד. ', '2022-02-08 10:39:12', 1, 1),
(20, '276d5e19fa5253aa12595f6fcf5cb89e', 'אנונימי', 'לא מומלץ בכלל, עדיף לקחת קורס אחר יותר פרקטי, הקורס מתחיל בצורה מעניינת למשך 3-4 הרצאות ראשונות, אחר כך מתחילים ללמוד על התוכנה ששמשתמשים בה לתרגיל בית 2 ומפה זה רק יורד למטה, ההרצאות לא קשורות למבחן והמבחן יחסית קשה, לא מובן איך ללמוד למבחן גם כי אין מבחנים לדוגמא ואין חומר רלוונטי', '2022-02-12 17:12:01', 0, 1),
(41, 'b859801e2dcf19f8d1787c9471081e3e', 'רוני', 'אין ספק שהקורס משעמם, אך ממליץ מאוד לקחת אותו, בעיקר אם יש גישה להרצאות מוקלטות. הסיבה היא שאין מתמטיקה אלא רק עקרונות של דחיסה, וכך גם המבחן: אמנם עמוס, 3 שעות של כתיבה, אבל נמרוד בודק את השאלות בצורה כ\"כ נחמדה שהוא נותן את רוב ואף כל הנקודות על נימוק הגיוני בהתאם לעקרונות שנלמדו. בנוסף, שיעורים ממוחזרים ובחנים שבועיים קלים (אין מה להתעמק לא באלה ולא באלה כי יש בערך 15 שנה של מבחנים שאפשר לחרוש לפני המבחן ולהוציא ציון טוב מאוד בקלות יחסית).', '2022-02-20 17:28:54', 0, 1),
(27, '7ed86fef23767083d68600cd6e63429a', 'עמית', 'קורס סביר, אור העלה את הרמה של המבחן כך שהמבחן יחסית קשה. המבבחן עדיין בנוי מ 3 שאלות של 20 נק כל אחת עם 40 נקודות חינם. השאלה הראשונה יחסית קלה ואם נמצאים ברוב ההרצאות ומבינים את החומר ברמה בסיסית אמורים להצליח. השאלה השנייה כבר יותר קשה ודורשת הבנה של החומר והשאלה השלישית כבר קשה ובשביל להצליח לפתור אותה צריך להגיע לכל ההרצאות, להתעמק בחומר ולפתור במהלך הסמסטר את התרגילים המומלצים שאור מפרסם. עדיין יש אפשרות לעשות עבודה חלופית', '2022-02-24 12:37:11', 0, 1),
(17, '7ed86fef23767083d68600cd6e63429a', 'עמית', 'קורס טוב. החומר מעניין וחשוב, והקורס הוא קורס קדם לקורסים מעניינים וחשובים. הקורס לא קשה ממש אבל גם לא כזה קל, כן משלב מתמטיקה. ריטה מרצה די משעממת אבל התרגולים עם עלאא היו מאוד מעניינים ומובנים ועזרו מאוד עם הבנת החומר', '2022-02-24 12:44:06', -1, 1),
(17, '1f39a9aebba36f422ddb0b694c8c8e8d', 'איתי', 'הקורס היה טוב בעיניי. ריטה מרצה נחמדה מאוד אבל אני חושב שההסברים והמצגות שלה היו קצת מסורבלים לפעמים ולא תמיד ברורים. הייתי בקבוצת התרגול של עלאא והוא הצליח להעביר את כל הקונספטים בצורה פשוטה. הציון מורכב מ80% מבחן ו20% תרגילי בית שהם מגן, התרגיל הראשון והשלישי לא לקחו כל כך הרבה זמן, התרגיל השני היה קצת יותר כבד. שני המועדים היו הוגנים מאוד בעיניי ואפשר היה להצליח בשניהם. ', '2022-03-02 12:27:15', 0, 1),
(55, '189a8828aa2275f6c9651774e86494d5', 'איתן שרעבי', 'בקצרה, לא מומלץ. בואו נתחיל מזה שאור מםרסם את הקרוס בתור הרצאות של מרצים מובילים מכל העולם ובתכלס חצי מהם מאוניברסיטת חיפה. מילא, אבל גם ההרצאות עצמן ברובן משעממות, לא מועברות טוב, ובבירור לא הושקע בהן הרבה (ברובן, לא בכולן). בהתחלה אור אמר שיהיה פרויקט לקורס, ושכנרא מאמצע הקורס יתחילו לעבוד איתנו עליו ויהיה ליווי כדי שזה לא יפול עלינו, בפועל, הסמסטר נגמר מזמן ואין זכר לפרויקט, ואור גם לא עונה למיילים ולא מסביר מה המצב. סך הכל אפשר לקבל ציון סביר בקורס (85) בלי יותר מדי השקעה, אבל רוב הקורס פשוט משעמם ומייאש.', '2022-06-24 15:09:01', 0, 1),
(58, '9507d350e3d66cda33a0e32cf1924b58', 'אנונימי', 'הקורס כבד, עמוס במידע אבל אחד החשובים ביותר שיש בתואר הזה. המתרגל היה מעולה, המרצה לא ממש מובן. אולי זה בגלל שחשבתי שיהיה דומה למבחני ריטה, אבל המבחנים אצלו קשים יותר.. ', '2022-06-30 13:09:18', 0, 1),
(11, 'e7ea87ae0f62849c9ae3c2465b812d7f', 'אנונימי', 'קורס נחמד אך מלא חומר (ממש מרגיש כמו שיעורי היסטוריה), התרגולים לא חופפים להרצאות והתרגילי בית לא קשורים לחומר בכלל. באופן כללי רחל מרצה נחמדה אך מאוד מפוזרת לפעמים והמתרגל רועי די מבריז רוב הזמן אבל שהוא מגיע הוא יודע לענות טוב והוא מאוד בקיא בחומר.', '2022-07-03 08:52:02', 0, 1),
(69, 'e7ea87ae0f62849c9ae3c2465b812d7f', 'אנונימי', 'רונן המרצה הכי מדהים שלמדתי איתי. מרצה מסודר,מסביר היטב, מקסים וסבלני. רק בזכות רונן הצלחתי בקורס וזה קורס מאוד מעניין , מטורף לראות איך כל מה שלמדנו כל התואר מתחבר פתאום. ממליץ בחום לקחת עם רונן (הוא גם מאוד פייר בבדיקה). לעומת זאת המתרגל אור- מתרגל גרוע,לא סבלני,לא פייר בבדיקת המבחן, מדבר בזלזול ובאופן לא מכבד לסטודנטים בתרגולים ,לא 100% בקיא בחומר, לא הועיל להבנת החומר בשום צורה!', '2022-07-03 08:56:40', 0, 1),
(45, 'c828845fa2d93f24eaff8f35c01c4267', 'אנונימי', 'קורס סופר חשוב ! , ממליץ בחום לכל מי שעושה אותו לא לעשות עם אלק , הוא בא בקטע להכשיל ולא לעזור , אם אתם יכולים לדחות תדחוווו! כיתה שלמה נכשלה איתו במועד א ולא עשה עם זה כלום ! ', '2022-07-03 09:14:28', 0, 1),
(61, '8ba816d18469b7f3645e86fcdef628d9', 'אנונימי', 'קורס בינוני מינוס מבחינת ללמד תכנות מונחה עצמים, אבל הוא בסדר. הבעיה האמיתית היא המבחנים, שבהם רוב הניקוד הוא לא על עקרונות של תכנות מונחה עצמים, אלא על האם אתה זוכר תכונה איזוטרית של c++, ממש להתעסק בקטנות ולא בחומר עצמו. עם זאת, רוב השאלות האלה ממוחזרות, אז לא באמת צריך לדעת שום דבר, אפשר פשוט לעבור על המבחנים הקודמים של דן ולהמשיך הלאה, אז הממוצע גבוה. בקורס שלנו היה קצת בלאגן איתו, היו 3 טעויות במבחן ולכן הרבה קיבלו נקודות חינם, אבל לקח הרבה כדי לשכנע את דן לפרסם את התשובות כי הוא סירב להודות שאולי יש טעות. בסוף הסתדר והממוצע כן מאוד גבוה, אז אין דאגה.', '2022-07-03 13:24:22', 0, 1),
(57, '8ba816d18469b7f3645e86fcdef628d9', 'אנונימי', 'אחלה מרצה, מפרגן ממש בבדיקת מבחנים. אישית עשיתי בחינה זוועתית, לא ידעתי בכלל איך עושים דטרמיננטה, אבל קראתי את הדף עזר והסברתי את מה שאני כן מבין בכל סעיף והוא נתן ניקוד חלקי על כל מה שכן הצלחתי להסביר, בסוף הציון הגיע ל70. פשוט מדהים, אפילו אני בקושי הייתי נותן לעצמי 40 אם הייתי הבודק. (ההרצאות עצמם כיפיות, הוא תמיד מתמקד באיך החומר תורם לנו ספציפית במדעי המחשב, אבל אני חייב להודות שלא נכחתי ברובם)', '2022-07-03 13:29:41', 0, 1),
(61, 'a0e7fb9bbb0d686cc7171427ae7a2936', 'אנונימי', 'לבוא להרצאות שלו זה יותר ללכת לאיבוד מאשר להתמקד, לפעמים המרצה בעצמו לא יודע באיזה נושא הוא ובאיזה הרצאה הוא נמצא מבחינת כרונולוגיה, ההרצאות לפעמים יותר מבלבלות ממלמדות. המבחן מאוד בוחן זכרון ודברים שאין להם צורך בהבנה מעמיקה על תכנות מונחה עצמים, אלא פשוט לזכור איך דברים עובדים בC++ והכל יהיה בסדר. מצפה שנזכור בעל פה מימושים של דפוסי עיצוב במקום שנדגים שימוש בהם בפועל.. מבחני זיכרון פחות מעיקים מזה. קורס עם הרבה פוטנציאל להרחבת הידע והמיומנות, מתבזבז בגלל מרצה לא משהו, כנראה שבסמינריונים/מעבדות הוא יותר מקצועי אבל בתור מרצה הוא על הפנים. המתרגל (לרמן) היה מעולה, בזכותו המבחן היה אפשרי וזה הרגיש שהוא היה גם המרצה וגם המתרגל בקורס. ממליץ על לרמן, לא ממליץ על פלדמן', '2022-07-04 08:20:15', 0, 1),
(62, 'a0e7fb9bbb0d686cc7171427ae7a2936', 'אנונימי', 'שולי מרצה מעולה, מספק חומרי לימוד עצמאיים מעולים (הקלטות של הרצאות, הסברים מעמיקים) ומעביר את החומר באופן אינטואיטיבי ומובן.', '2022-07-04 08:27:35', 0, 1),
(45, 'baf9776bc66478916e4242539c4da3f5', 'אנונימי', 'קורס לא קל, מלא חומר , והמרצה מזעזע! לא מובן אין חומר ללמוד הוא מלמד נושאים שאף מרצה אחר לא מלמד באותו קורס!! ממוצע נמוך מאוד ואין אפילו ציון אחד של עובר (51+) פשוט לברוח! תדחו חבל באמת', '2022-07-04 22:01:33', 0, 1),
(62, '2bcee65362f6540f0a7689db9ea9c03a', 'אנונימי', 'שולי מרצה מעולה! הוא דואג לתת הרבה מאוד חומרים במודל, יש הקלטות מלאות ומושקעות לכל נושא והמבחנים שלו פיירים מאוד.', '2022-07-05 08:20:36', 0, 1),
(69, 'e8e848fa16ef2fa32e336765d31f4112', 'אדם', 'רונן מעולה וגם אור', '2022-07-16 13:35:32', 0, 1),
(58, '9c9bfbba26f81f4e0ff31d67b9405cdf', 'שירה', 'קורס מעולה ולא קשה ממליצה מאוד', '2022-08-03 12:37:43', 0, 1),
(50, '83842ec28f0a5ee1cf4b293ca5769907', 'אנונימי', 'נהנתי מהקורס. לומדים את הבסיס של קריפטוגרפיה תיאורטית (ממש בונים מ\"יסודות\", כל מני הנחות פשוטות, מבנים קריפטוגרפים מסובכים). סה\"כ קורס מעניין ונחמד, ומי שבא להרצאות אצלנו היה יכול לעשות עבודה. ממליץ בחום למי שמחבבים נושאים יותר תיאורטים', '2022-08-10 18:54:09', 0, 1),
(31, '1e9ed1bfb4da5dac0baf5dc5c97c1baf', 'אנונימי', 'קורס לא ממש קל אבל ציונים טובים למי שמסיים, כל הרצאה בגדול על נושא אחר בתחום, תמיד מתחילים מתאוריה ומשליכים לפרקטיקה ולתרגיל בית תכנותי. רוב הציון מורכב מתרגילי בית. הקורס אומנם פתוח לכל מי שסיים גרפיקה ממוחשבת אבל מאוד מומלץ לדעתי לא לקחת לפני שמסיימים אלגברה ב.', '2022-08-21 19:08:03', 0, 1),
(73, '7127488f5651ddddf87107cf6ab39839', 'רינה', 'אחלה מרצה בעולם', '2022-08-28 09:54:47', 0, 1),
(28, '6e84914f761e0b6bb6754457c0e60e39', 'עידו', 'רונן מרצה מעולה והוגן, המבחן שלו מאוד מובן וברמה וממשיך את הרמה של הקורס עצמו.', '2022-09-03 03:20:56', 0, 1),
(49, '21b8c3965b038b3bcb0b42ccd7610c14', 'אדם', 'לא מומלץ, רק לאמיצים קורס מעניין אבל לא קל', '2022-09-04 14:41:51', 0, 1),
(66, 'ae9abb5d2cfe0f97f41ac2f744924d1d', 'עינת', 'אורן מעביר מדהים. הקורס היה מתוקשב עוד לפני הקורונה. אני למדתי רק מההקלטות. הקורס לא קל (התרגולים ותרגילי הבית דורשים השקעה), אבל בסה\"כ המבחן היה אפשרי.', '2022-09-11 12:08:15', 0, 1),
(68, 'ae9abb5d2cfe0f97f41ac2f744924d1d', 'אנונימי', 'אני מודה שלמדתי רק מהתרגולים ולא הגעתי להרצאה אחת, אבל זה הספיק לי והיה מבחן סבבה :)', '2022-09-11 12:08:53', 0, 1),
(5, 'ae9abb5d2cfe0f97f41ac2f744924d1d', 'עינת', 'למדתי עם נגה לפני 3 שנים והייתה חוויה מעולה. נגה מעבירה מסודר וקל להבנה. המבחן היה בסדר גמור והיה אפשר לקבל ציון טוב עם השקעה במהלך הסמסטר. היתרון הגדול של נגה שהיא מעבירה מעולה, החיסרון שלה שהיא קטלנית במבחנים ומורידה המון נקודות על שטויות.', '2022-09-11 12:16:39', 0, 1),
(11, 'f3df96086135b5ca5644368a946370c9', 'אנונימי', 'קורס עמוס מאוד מאוד מאוד. החומר לא קשה בהכרח אבל יש המון חומר לזכור ואין אפשרות לדף עזר בבחינה. רחל נחמדה רק לסטודנטים שהיא מכירה ממהלך הסמסטר ועל כן לא מומלץ לצפות ליותר מדי אם לא הגעת להרצאות... המבחנים אומנם לא ברמה גבוהה מדי אבל כן מכילים שאלות מכשילות שזה משהו לשים דגש עליו. בעיקר קורס שינון יותר מאשר קורס הבנה מלבד שאלות הזיכרון הוירטואלי שהן שאלות מתמטיות.', '2022-09-18 00:27:32', 0, 1),
(13, 'f3df96086135b5ca5644368a946370c9', 'אנונימי', 'מרצה נחמד באישיות אך מאוד מפוזר בעת ההרצאה. תתכוננו להרבה מאוד צבעים על מסך בודד. בתור מרצה מקורסי המתמטיקה הוא דקדקן מאוד וחשוב לו על כל משפט הסבר מלא. המבחן לא ברמה נוראית אבל הסבר המשפטים המדויק כן יכל לפגוע מאוד. לקחתי את הקורס גם עם יעל ויכל לאמר שעם יעל הנושא היה יותר מובן אבל עקרונית לעבור עם עמי זה יותר מאפשרי, ככה שאין מה לפחד. מי שעובד קשה ולומד איך לכתוב תשובה יוכל לעבור את הבחינה עם ציון מכובד', '2022-09-18 00:35:33', 0, 1),
(45, '9507d350e3d66cda33a0e32cf1924b58', 'אנונימי', 'אם אין ברירה, לדחות', '2022-09-24 10:25:38', 0, 1),
(89, 'a0e7fb9bbb0d686cc7171427ae7a2936', 'עידן', 'מרצה טוב, הקורס לא קשה. יש המון חומרים זמינים, התרגולים של רוז זה זהב טהור וארז כותב בחינות לא קשות.', '2022-10-06 10:26:20', 0, 0),
(6, 'c6fa26eab38f7f66ff96b584b3bfaf7d', 'אנונימי', 'אני נהנתי מאוד מהקורס, יורי מרצה לא קל אבל הסתדרתי איתו, סהכ צריך באמת לאהוב את הנושא בשביל להנות מיורי', '2023-02-17 20:07:34', 0, 0),
(3, 'c6fa26eab38f7f66ff96b584b3bfaf7d', 'אנונימי', 'אני לקחתי את הקורס בסמסטר קיץ. הקורס הכי מאכזב שהיה לי אבל מאה קל. לא למדתי כלום, היא לא הוכיחה כלום אבל סהכ חמודה באישיות', '2023-02-17 20:08:42', 1, 0),
(56, 'ed6e8c7aaddc2050b2dd8be43935ef48', 'ליעד', 'מורן מרצה ברמה גבוהה מאוד. לפעמים קשה להבין בהרצאה את עומק החומר אך חשוב לא לוותר על הבנה עמוקה ולהגיע לשעות קבלה. המבחנים של מורן קשים ודורשים הבנה עמוקה.', '2023-05-02 13:01:10', 0, 0),
(2, '1cb4777513aa630295ea37bb084bcfdf', 'אנונימי', 'אור מרצה מדהים, ענה לכל שאתה בסבלנות כמו שצריך. ת״ב יחסית קשים, חשוב לעשות אותם שצריך ואז ההכנה תקראי. המבחן הרבה יותר טובה, כמויות של חומר לתרגל, פידבק מעולה על הידע, לי אישית אור עזר ונתן פידבקים על מבחנים משנים קודמות שפתרתי ככה שהגעתי למבחן ובכלל היה נדיר. חשוב להשקיע ולקחת את הקורס בידיים ולעקוב כל הרצאה וצא לתפוס פער.', '2023-05-30 12:49:31', 0, 0),
(32, '9507d350e3d66cda33a0e32cf1924b58', 'שרון', 'קורס נפלא. אמנם תיאורטי, אבל הכל בו רלוונטי לתעשייה וכל דבר שקשור בראייה ממוחשבת (מכוניות אוטונומיות, רובוטיקה) משתמש בקורס הזה. התרגילים (תכנותיים) מעניינים והציונים טובים אם משקיעים בתרגילים (וגם בתיאוריה)', '2023-08-29 19:48:45', 0, 0),
(89, '67bda7af127d02307a305bfa2254d3f3', 'אנונימי', 'מאורגן מאוד, מסביר ברור, ומעלה את החומרים למודל. הוא זמין במייל לשאלות', '2023-08-29 21:26:18', 0, 0),
(8, '67bda7af127d02307a305bfa2254d3f3', 'אנונימי', 'הקורס לא פשוט אבל המרצה מצוין', '2023-08-29 21:28:27', 0, 0),
(58, '67bda7af127d02307a305bfa2254d3f3', 'אנונימי', 'דן לא מרתק במיוחד. תרגילי הבית הם מגן אך מומלצים כדי להבין את החומר. המבחן הסופי סביר בהחלט', '2023-08-29 21:30:41', 0, 0),
(2, 'f3df96086135b5ca5644368a946370c9', 'יובל', 'אור משקיע מאוד במצגות שלו ובהסבר שלו. מאוד מומלץ במהלך השנה עצמה אך מאוד קשוח במבחנים. גם במבנה הבחינה וגם בערעורים. ', '2023-09-02 21:31:11', 0, 0),
(3, 'f3df96086135b5ca5644368a946370c9', 'יובל', 'מרצה נחמדה שמלמדת בצורה מאוד דומה לתיכון (לפי מיטב ידיעתי היא גם מלמדת בתיכון). הנוכחות אצלה גם חובה והמבחנים שלה ידועים כקלים. אצלי ספציפית אבל המתרגל בנה את המבחן מה שהיה בעייתי...', '2023-09-02 21:32:19', 0, 0);
INSERT INTO `Tcomments` (`idquestion`, `ref`, `name`, `content`, `time`, `rank`, `seen`) VALUES
(89, 'f3df96086135b5ca5644368a946370c9', 'יובל', 'מרצה מצחיק, משתדל להסביר בצורה מעניינת כמה שניתן את הנושא. מאוד מאוד הגון.', '2023-09-02 21:33:10', 0, 0),
(62, 'f3df96086135b5ca5644368a946370c9', 'יובל', 'מרצה טוב ומעניין. במבחן לעומת זאת יכל להיות קשוח עם הבדיקה. ', '2023-09-02 21:33:53', 0, 0),
(11, 'f3df96086135b5ca5644368a946370c9', 'יובל', 'רחל לא המרצה הכי נחמדה... לא באישיות ולא בבחינה. המבחן עצמו אולי לא ברמה הכי גבוהה בהכרח אבל היא בהחלט בונה שאלות במטרה להכשיל (בין אם על ידי נוסח, אמריקאי שיכלה להיות בו יותר מתשובה אחת נכונה או טעויות במבחן). גם בערעורים אם היא לא מכירה אתכם ואוהבת אתכם מההרצאות, קיים סיכוי שהיא לא תבוא בגישה הנחמדה ביותר... לקורס אין באמת מצגות מכיוון והוא נלקח מתוך הספר לכן חומרי הלימוד העיקריים הם התרגולים שלא באמת מכסים את כל החומר. ', '2023-09-02 21:35:57', 0, 0),
(28, 'f3df96086135b5ca5644368a946370c9', 'יובל', 'רונן מרצה טוב מאוד. מלמד בצורה מעניינת, מאוד קשוב ונחמד וגם המבחנים שלו בנויים בצורה הוגנת להפליא. לקחתי איתו מודלים חישוביים. הבעיה היחידה שהייתה לי איתו היא שהוא לא העלה את המצגות עצמן של ההרצאה אלא נתן סיכום של מרצה אחר, דבר שלא לגמרי הסביר את הכל בצורה מלאה ו/או מובנת.', '2023-09-02 21:37:15', 0, 0),
(45, 'f3df96086135b5ca5644368a946370c9', 'יובל', 'לא מומלץ... המבחן מתוך 120 נקודות אם זכור לי נכון, ובכל זאת הממוצעים אצלו עומדים על פחות מ50 באופן קבוע.... (במועדים שלי הממוצעים היו 25 ו36...). הוא לא מעלה לאתר את החומרים בצורה ממש ברורה, בונה מבחן ברמה גבוהה וקשוחה. מה שכן, הוא מאוד מרחם בעירעורים - אז גם תלמיד שמצא את עצמו עם 0 במבחן, יכל להגיע לעובר משום מקום. נותן בונוס של 10 נקודות למי שנוכח בשיעורים. לסיכום, למרות כל הבונוסים, מאוד לא מומלץ...', '2023-09-02 21:39:29', 0, 0),
(52, 'f3df96086135b5ca5644368a946370c9', 'יובל', 'מרצה מדהים,קשוב והוגן. החיסרון הבולט בקורס איתו אבל זה שאין שיעורי בית - במחשבה ראשונה זה נשמע כמו דבר טוב אבל ללא תרגול של החומר מאוד קשה להבין איך לענות תשובה ולבדוק הבנה. הוא כן נתן לנו לתרגל מדי פעם במהלך השיעור אבל מאוד קשה להסיק מזה אם התשובה נכונה או לא ולמה. בסך הכל מרצה מאוד נחמד וטוב מלבד הקטע של שיעורי הבית. ', '2023-09-02 21:41:01', 0, 0),
(57, 'f3df96086135b5ca5644368a946370c9', 'יובל', 'לא מומלץ. במהלך הסימסטר עצמו הוא באמת מרצה מדהים שעונה על שאלות,זמין, מנסה לעשות את החומר מעניין ובאמת כל דבר חיובי שאפשר לאמר, ניתן לאמר עליו. הבעיה היא שלקראת הבחינה הוא מרגיע שהבחינה תיהיה מאוד הוגנת, ובסוף מקבלים בחינה מזעזעת וקשה מאוד. אצלנו הממוצע היה נמוך מאוד ורק אחריי מאבק ממושך הוא הסכים לקבל אנשים לפי ציונים סופיים עם פקטור של 10 נקודות... בהמשך לקחתי איתו גם את חדו&quot;א 2 והגענו לבעיה מאוד דומה. אז במהלך הסימסטר באמת מרצה מדהים, אבל הבחינה שלו ברמה גבוהה מאוד. ', '2023-09-02 21:43:52', 0, 0),
(13, 'f3df96086135b5ca5644368a946370c9', 'יובל', 'דרך טובה לתאר את המרצה היא מתמטיקאי. הוא מאוד מבולגאן ומאוד חשוב לו הפורמליות. הוא מלמד יותר ומה שהוא מלמד הוא מלמד יותר לעומק. אין ספק שבהשוואה למרצים אחרים לתחום הממוצע אצלו יהיה יותר נמוך, אבל בהחלט יהיה יותר ידע וברמה עמוקה יותר. ', '2023-09-02 21:45:33', 0, 0),
(39, 'f3df96086135b5ca5644368a946370c9', 'יובל', 'לא מומלץ... מסביר בצורה מאוד מבולגנת, לא הדרגתית ולא ברורה. כאשר לקחתי את הקורס בשנה א&#039; שלי הוא ישר נכנס למתמיקה והתחיל לרוץ, דבר שהכניס אותי ללחצים וחרדות מהתואר כולו... גם את החומר הוא לא מסביר ברור וגם רמת הבחינה גבוהה מאוד. מעביר לפי ציון סופי ולא לפי ציון בחינה. מרצה מאוד חכם, פשוט לא מספיק מיומן בתחום ההוראה.', '2023-09-02 21:47:07', 0, 0),
(12, 'f3df96086135b5ca5644368a946370c9', 'יובל', 'מרצה חביב. מסביר את החומר בצורה מעניינת, הגון במבחנים (יש גם מועד אמצע) וקשוב לסטודנטים. ', '2023-09-02 21:48:28', 0, 0),
(8, 'f3df96086135b5ca5644368a946370c9', 'יובל', 'אורן יכל להיות מרצה קשוח, לפעמים טיפה מבולגאן ולא בהכרח הכי נחמד אבל הוא בהחלט מעניין ויודע לרכז בחומר. הקורס עצמו קשה אך לא עמוס (כמות מבני הנתונים שלומדים היא לא ענקית ואפילו מסיימים את החומר כמה שבועות לפי הבחינה, אבל להבין כל נושא דורש הרבה). הקורס ככלל מעניין ממש ושווה למי שמתעניין. בעקבות הקושי שלו, הייתי אומר שהוא מתאים רק למי שמוכן להשקיע בקיץ.', '2023-09-02 21:53:24', 0, 0),
(58, 'f3df96086135b5ca5644368a946370c9', 'יובל', 'קורס מעניין אך מאוד מבולגאן... בכל שיעור לומדים נושא אחר ואין ממש קשר בינהם. הקורס עצמו הוא פחות או יותר המשך להסתברות. המצגות עצמן גם לא הכי ברורות בהכרח... המבחן אצלנו של מועד א&#039; היה עם ציונים מאוד גבוהים. בסך הכל קורס מאוד מעניין וכשמוצאים הסבר טוב, הרמת קושי לא גבוהה כל כך, פשוט צריך לסדר את כל הנושאים כי יש הרבה והם קצת מבולגאנים...  ', '2023-09-02 21:56:18', 0, 0),
(31, 'f3df96086135b5ca5644368a946370c9', 'יובל', 'קורס קשה ועמוס מאוד מבחינת רמה, אבל ה&quot;תשלום&quot; על כך הוא הציון הגבוה עד מאוד. רועי מרצה נחמד מאוד מבחינת ציונים בשיעורי הבית ובמבחן אבל לעיתים מאוד לא ברור (גם בהסברים שלו וגם בכוונה שלו). לעיתים קרובות לא ברור הקשר בין ההסבר התיאורטי (מה אנחנו מנסים לעשות), למעשי (הנוסחאות והאלגוריתמיקה) לביצועי (איך מתכנתים את זה)... ידרוש המון שעות עבודה. הנושאים עצמם מעניינים בסך הכל אבל שוב -לא תמיד ברורים...', '2023-09-02 21:59:05', 0, 0),
(41, 'f3df96086135b5ca5644368a946370c9', 'יובל', 'קורס מלא בתוכן עם מרצה נחמד מאוד. הקורס עצמו מאוד משעמם ומבלבל במהלך הלמידה, אבל נמרוד מאוד מתחשב גם בשיעורי הבית, גם במבחן וגם בבונוסים במהלך השנה. המבחן עצמו ארוך אבל עם חומר פתוח לגמרי ונמרוד מתחשב מאוד. מה שכן, נמרוד נזהר לא לתת חומרים כדי לעודד סטודנטים להגיע להרצאות. מאוד מומלץ לקחת! ', '2023-09-02 22:00:47', 0, 0),
(16, 'f3df96086135b5ca5644368a946370c9', 'יובל', 'החומר בהרצאות הוא מילה במילה כמו החומר של המצגות שיש באתר החומרים (האתר הזה). נגה לא מעלה חומרים לאתר. שיעורי הבית חביבים בסך הכל ולרוב מאוד דומים לשנים קודמות. המבחן לעומת זאת כמו שאחרים רשמו הוא מזעזע. נגה בוחנת על שינון בעל פה של הוכחות (כל הוכחה קטנה יכלה להיות במבחן) והיא מאוד קשוחה עם הנקודות. לא בהכרח מומלץ, אבל מי שכן לוקח שידע שבמהלך השנה הקורס יהיה רגוע מאוד ואף קל לפעמים - אבל בבחינה יהיה מאוד קשה ומתקיל. ', '2023-09-02 22:03:57', 0, 0),
(22, 'f3df96086135b5ca5644368a946370c9', 'יובל', 'רועי מרצה לא מובן כל כך, אבל נדיב מאוד בציונים. החומר עצמו מאוד עניין עד שיורדים למתמטיקה ושם הוא נוטה להיות לא ברור. התרגילים במהלך הסימסטר מסתמכים זה על זה אז כדאי מאוד שהכל יעבוד לקראת התרגיל הבא. בסך הכל קורס עם ציונים גבוהים מאוד שיידרוש הרבה מאוד זמן ועבודה מהסטודנט. מומלץ עם הקורס לא עמוס. אם מכירים מישהו שלקח את הקורס בעבר הדברים יהיו הרבה יותר ברורים. כשעשיתי את הקורס היתה אפשרות לבחינה בעל פה ובכתב. בבחינה בעל פה הוא היה נחמד מאוד גם למי שלא ידע בהכרח כל כך, אבל בבחינה בכתב הוא כן היה מעט יותר קשוח.', '2023-09-02 22:06:53', 0, 0),
(30, 'f3df96086135b5ca5644368a946370c9', 'יובל', 'מרצה טוב בסך הכל. הוא מאוד חברותי עם הסטודנט ומאוד מתחשב עם הציונים אך נוטה להיות לא ברור - לא רק מבחינת החומר שהוא מעביר אלא גם מבחינת התשובות שהוא נותן על שאלות לסטודנט או בבקשות שלו. ', '2023-09-02 22:08:18', 0, 0),
(26, 'ac1cdf727d87f9d98a5326f2705fd1fc', 'אנונימי', 'מאד לא ממליץ, מדובר בחומר שהוא כנראה חדש למי שנרשם אלא אם כן עשית את הקורס התיאורטי שלה, עדי לא זמינה כמעט והבעיה הבאמ גדולה שהיא מצפה לרמת מאמר בזמן של קורס. היא דורשת כתיבת בסגנון מאמר, מצגת וקוד ללא הנחייה או תמיכה אפילו במציאת נושא. אם בסוף אתה לא עומד בדרישות המדויקות שהיא רוצה (אבל לא מסבירה) אז כנראה תיכשל. החומר עצמו יכול להיות מעניין אבל מאד לא מומלץ לאור המרצה ואיך שהיא מנהלת את זה.', '2023-09-07 07:38:38', 0, 0),
(58, '25146978d089610b2a80a9c9ec71a2ca', 'דוד', 'קורס קצת מבולגן, אבל עדיין מעניין ולא קשה. תרגילי הבית עזרו מאוד להבין את החומר. המבחן היה סביר ואפילו קל.', '2023-09-08 07:54:23', 0, 0),
(11, '17c77cc0944b52b7512f575914a19fe3', 'אנונימי', 'מה שיובל אמרה', '2023-09-10 18:44:41', 0, 0),
(16, '25146978d089610b2a80a9c9ec71a2ca', 'אנונימי2', 'נגה מסבירה די טוב את החומר בסבלנות ובצורה מסודרת. תרגילי הבית היו ממוחזרים ולרוב די קלים וקצרים. המבחן הוא מבחן ידע ודורש שינון של כל החומר בעל פה, ללא חומר עזר (אבל לא כל כך הרבה חומר, ניתן לתמצת את כל הקורס על 2-3 דפים כולל הוכחות). נגה אינה מעלה סיכומים למודל מסיבות אידאולוגיות כלשהן, אבל קיים סיכום שלה מתקופת הקורונה באתר החומרים, ונגה מלמדת מתוכו מילה במילה עד רמת הדוגמאות.', '2023-09-13 09:46:03', 0, 0),
(11, '25146978d089610b2a80a9c9ec71a2ca', 'אנונימי', 'לא מרצה טובה. קורס עמוס ומשעמם, מלא בפרטים טכניים לא רלוונטים. תרגילי הבית (לתכנת כל מיני דברים בלינוקס) לא ממש מכינים למבחן, אם כי עוזרים להבין את החומר. המבחן היה נוראי. רחל לא נכחה במבחן, הייתה טעות באחת השאלות, בשאלות האמריקאיות כל מספר של תשובות נכונות יתכן (כולל אפס), למרות שהדבר לא מצויין על טופס הבחינה ולא נאמר בשיעורים. באופן כללי המבחן הרגיש מבולגן ורחל מנסה להכשיל בו בכוונה (כמו שהיא שאמרה במפורש). למרות כל הנ&quot;ל, הממוצע היה סבבה ותרגילי הבית (30%) הוסיפו הרבה לציון הסופי.', '2023-09-13 10:02:28', 0, 0),
(28, '25146978d089610b2a80a9c9ec71a2ca', 'אנונימי', 'אולי המרצה הכי טוב בחוג. למדתי אצלו מודלים חישוביים והיה מושלם. רונן מסביר מעולה שגם ילד בכיתה ו יבין. גורם לכל חומר להישמע מעניין. המבחן היה מאוד הוגן וגם בערעורים הוא מאוד מתחשב. ', '2023-09-13 10:12:39', 1, 0),
(56, '25146978d089610b2a80a9c9ec71a2ca', 'אנונימי', 'חומר לא פשוט ולפעמים קצת קשה להבין את מורן. כדאי להחזיק את הסיכומים פתוחים בזמן ההרצאה כדי לא ללכת לאיבוד. המבחן קשה ומורן דורש הוכחות מפורטות. בדרך כלל יש פקטור מכובד שמפצה על זה, והרוב עוברים עם ציונים סבירים. סה&quot;כ קורס מעניין ומרצה סבבה.', '2023-09-13 10:21:08', 1, 0),
(15, '25146978d089610b2a80a9c9ec71a2ca', 'אנונימי', 'הפכו את זה עכשיו לקורס בחירה, אל תקחו.', '2023-09-13 10:25:48', 0, 0),
(9, '255ad738bdf16f3c4f135c5b358b2374', 'ירדן', 'קורס משעמם אבל המרצה מדהים ונחמד ויש לו מבחנים קלים להוציא ציון טוב', '2023-09-21 12:45:20', 0, 0),
(33, '0ae4e80d0f131f45b6df54e46c672161', 'עידו', 'מעבדה שדורשת השקעה, פרוייקטים מעניינים אבל הכל קצת באוויר ולא ברור היה עם דן, פשוט זרקו עלינו &quot;פרוייקט&quot; שאין לך שום ידע קודם עליו ותסתדר, שורה תחתונה הוא לא סופר קשה, הקושי העיקארי זה להיכנס לעניינים ולהבין מה רוצים ממך בכלל ומה ומתי להגיש אפילו (הכל באוויר עם דן). יאמר לזכותם שממוצע 90 וסה&quot;כ ציונים יפים.', '2023-09-26 08:32:44', 0, 0),
(33, 'e7129b3efb03142bdd428a2b97cd95a7', 'נאיף', 'המעבדה קשה אבל המרצה מצוין וזמין כל הזמן לשאלות,ממליץ לעשות המעבדה.', '2023-09-27 19:54:23', -1, 0),
(11, 'fed5c8931f9e2cc4d102b48bccda5898', 'אנונימי', 'קורס כלכך חשוב וחבל שמתעסקים בו בעיקר בשטויות. ההרצאות מלאות בדיבורים באוויר והתרגולים והתרגילי בית ברמה של קורס במתנ&#039;&#039;ס. לא לומדים נושאים חשובים כמו מערכות מבוזרות ורשתות. מביך שזה הרמה של קורס שמועבר ע&#039;&#039;י ראש החוג.', '2023-09-28 13:44:45', 0, 0),
(94, '4fa1cf28721ac60f99076fa6ab1ac808', 'אלמוג', 'קורס מאוד חמוד לאוהבי אוטומטים. לומדים על אוטומטים מעל מילים אינסופיות, והמבחן לא היה קשה מדי. גיא מעביר את החומר באופן ברור לטעמי, ומפנה לחומר כתוב שממנו הוא מסכם אם מבקשים. היו 4 תרגילי בית לאורך הסמסטר, שאחד מהם היה רשות. מומלץ.', '2023-11-06 09:30:08', 1, 0),
(33, 'eb2c96e4f60c12bed0aea8b26397d56d', 'אנונימי', 'על פניו, הקורס לא נורא, אבל הגישה הנונשלנטית של המרצה הופכת את הקורס ללא מסודר ולא ברור. הדרישות מעומעמות ולא מובנות, יש פינג-פונג תמידי בין המרצה ל&quot;מנחים&quot;, וגם אם תתמידו ותגיעו לכל שעות הקבלה ותבקשו הבהרה לכל דרישה, שום דבר לא מובטח - אתם נתונים לחסדיו של דן. אמ;לק - לא מומלץ בעליל.', '2023-12-04 11:53:46', 0, 0),
(48, '67bda7af127d02307a305bfa2254d3f3', 'אנונימי', 'הסמינר עצמו לא מרתק במיוחד - מדובר על אוסף רדוקציות בין בעיות שונות. כל אחד מקבל מאמר עם כמה רדוקציות, וצריך להציג אותן. אורן לא מאוד מפרגן עם הציונים.', '2024-03-13 12:15:43', 0, 0),
(94, '67bda7af127d02307a305bfa2254d3f3', 'אנונימי', 'קורס נחמד מאוד. אמנם לפעמים לוקח לגיא רגע לחבר את קו המחשבה, אבל הוא מרצה מצוין ודואג שכולם יבינו. זמין מאוד במייל. תרגילי הבית הוגנים, והוא עוזר גם כשניגשים אליו עם שאלות על תרגיל הבית..', '2024-03-13 12:25:32', 0, 0),
(13, '01ffec7fe6c63c1f906f3bdf6282e471', 'אנונימי', 'לא מומלץ בכלל, עמי לימד את הקורס ברמה גובהה מידי משאר המרצים את הקורס חדוא 2. גם המבחנים שלו מאוד קשים , אצלי אין אחד שקיבל מעל 60 במועד א זה אומר הכל', '2024-04-13 07:41:09', 1, 0),
(89, '01ffec7fe6c63c1f906f3bdf6282e471', 'אנונימי', 'הקרוס היה סבבה, תתכוננו לזה שלא ממש תבינו את ההרצאות בפעם הראשונה ויקח לכם זמן להבין את החומר. המבחנים שלו הוגנים.', '2024-04-13 07:48:03', 1, 0),
(66, '01ffec7fe6c63c1f906f3bdf6282e471', 'אנונימי', 'אורן מעביר את הקורס בצורה ענייני ומעניינת. תרגילי הבית קשים וגם המבחנים לא פשוטים. אני ממליץ שתשקיעו בקורס אם תרצו ציון טוב.', '2024-04-13 07:53:24', 1, 0),
(10, '01ffec7fe6c63c1f906f3bdf6282e471', 'אנונימי', 'יאיר מלמד סביר, תתכוננו שהוא לא מלמד טוב design patterns ועוד שואל שאלה של מימוש של זה במבחן, אז אם אתם רוצים ציון גבוהה תשקיעו בללמוד design patterns (ואת כל הסוגים לא רק הפופולריים! , אצלי הוא שאל על observer) . הוא בודק בצורה מאוד הוגנת ומפרגן בבדיקה. ', '2024-04-13 08:02:15', 1, 0),
(13, '85bdbeb086106442fbd4b4b81960734b', 'אנונימי', 'לא ממליץ, תדחו את הקורס לסמסטר שעמי לא מלמד בו.', '2024-07-29 18:28:14', 6, 0),
(99, 'f0c09749dacc11dd7d5ced8475fdd816', 'אנונימי', 'אחלה של קורס, חומר מעניין. החצי הראשון תיאורטי, בחצי השני לומדים על מודלים גנרטיביים שונים (vaes, normalizing flows, diffusion models...)  ומממשים בתרגילי הבית. בעיקרון הקורס &#039;למידה עמוקה&#039; (נכון לסמסטר זה) לא מוגדר כקדם, אבל כן צריך רקע ברשתות נוירונים בשביל הקורס. ציונים גבוהים.', '2024-08-13 16:05:41', 1, 0),
(98, 'f0c09749dacc11dd7d5ced8475fdd816', 'אנונימי', 'לא מעניין ולא מומלץ. יוסי לא נחמד במיוחד, נכנס בדברי המציגים במהלך הצגת המאמר בלי סוף ומקשה על ההצגה.', '2024-08-13 16:10:04', 0, 0),
(14, 'f0c09749dacc11dd7d5ced8475fdd816', 'אנונימי', 'החומר לא מעניין כל כך.', '2024-08-13 16:12:57', 0, 0),
(72, 'f0c09749dacc11dd7d5ced8475fdd816', 'אנונימי1', 'הדבר העיקרי שיש להגיד לגבי המעבדה הוא שהיא עמוסה מאוד. אפשר בהחלט לקבל ציונים מאוד גבוהים, אבל העומס גדול מאוד. המטלות הן כתיבת קוד, שהוא בעצם מימוש של אלגוריתמים שנלמדים בכיתה, לצורך פתירת בעיות שונות. המטלות נבנות אחת על גבי השנייה, כך שכדאי לדאוג שהקוד יהיה מודולרי כדי שאפשר יהיה להשתמש בו ולשנות אותו בהתאם במטלות הבאות. חשוב לציין- המעבדה כוללת הרצאה שבועית במהלך כל הסמסטר (אין חובת נוכחות אבל צריך לדעת את החומר כדי לפתור את המטלות). בגדול לא ממליץ במיוחד. מה שכן, שי זמין כל הזמן, ומפציר בסטודנטים לפנות אליו לעזרה במייל/שעות קבלה/לאחר ההרצאה. מומלץ מאוד להיעזר בו, זה יכול להקל מאוד.', '2024-08-13 16:23:17', 0, 0),
(72, 'fdfe7b0fca5dcb1bcfaad1c4e418fb08', 'אלון', 'קורס לא פשוט בכלל, יש לציין שגם עמוס וגם צריך לעבוד לא מעט בקורס ומצד שני זאת מעבדה אז אי אפשר לצפות שנקבל הכל בכפית. השיעור מועבר בשקופיות ויש לציין ששי זמין מאד ותמיד עונה ומוכן לעזור ולתת מזמנו וזה חשוב. קחו את הקורס רק אם אתם מוכנים להשקיע את הזמן בקוד + בכתיבת הדוח, יש לציין שהדוח הוא המשמעותי כי שי יודע ש99% מהסטודנטים כבר הכירו את chatgpt וגם משתמשים בו באופן רחב ולכן הקוד פחות מעניין אותו אלא התעמקות העבודה בדוח... אפשר לקבל ציונים טובים מאד! פשוט תשקיעו.', '2024-09-01 18:10:39', 0, 0),
(14, 'fdfe7b0fca5dcb1bcfaad1c4e418fb08', 'אלון', 'קורס שבעזרת הפרויקט בו השגתי ראיון עבודה, המבחן קשה מאד והפרויקט עמוס אבל מהווה 45% מהציון לכן חובה לעשות זאת בגלל קושי המבחן.', '2024-09-01 18:13:04', 0, 0),
(52, '25e70e5001fd86b0a28690c87ab743ec', 'אנונימי', 'אחלה מרצה בעולם מלמד בצורה הכי מעניינת, הביא לנו מבחן כולו משוחזר חוץ משאלה אחת שהיתה חובה, אבל מועד ב&#039; היה קשה כפי שהבנתי.', '2024-09-13 12:37:30', 0, 0),
(56, '25e70e5001fd86b0a28690c87ab743ec', 'אנונימי', 'מרצה טוב מבחינת האישיות, הוא מסביר את החומר בצורה סבירה אבל קצת מדבר במהירות וקל מאוד ללכת לאיבוד בהרצאות ובפרט בהוכחות.      הביא לנו מועד א&#039; סביר יחסית והיה אפשר לקבל בו ציון גבוה כי היה פקטור מכובד מאוד, אבל מועד ב&#039; היה המבחן הכי קשה בקורס זה שראיתי עד עכשיו. ', '2024-09-13 12:41:45', 0, 0),
(100, '9507d350e3d66cda33a0e32cf1924b58', 'אנונימי', 'עשיתי את הקורס ב22-23. מעניין ומומלץ לכאלה שהתחברו להסתברות / אלגוריתמים אקראיים. עם זאת שימו לב שהקורס כבד מאוד ולמרות שהוא רק 3 נקודות, חומר בכמות של 4-5 נ&quot;ז.', '2024-09-24 13:48:10', 0, 0),
(101, '9507d350e3d66cda33a0e32cf1924b58', 'אנונימי', 'הקורס עצמו הוא מאוד חשוב בתחום של פתירת בעיות אופטמיזציה עם יישומים רבים, אבל דן לא יודע (או מנסה) ללמד אותו כמו שצריך וזה חבל. לא מומלץ. ההתנהלות היא כזאת: אם מגיעים לשיעורים אפשר לבקש ממנו להתחיל על פרוייקט - לממש או להבין מאמר, להראות שיודעים לפתור בעיות וכו.', '2024-09-24 13:49:30', 1, 0),
(102, '9507d350e3d66cda33a0e32cf1924b58', 'אנונימי', 'עשיתי את הקורס ב22-23. בעיניי לפחות ריטה היא מרצה מעולה למרות שהרבה מהחברים לא חושבים כך. החומר סופר מעניין וחשוב למי שמתעניין, זה הבסיס להכל בערך. עם זאת ההבנה הפרקטית תלוית מתרגל טוב וחובה שותף טוב בקורס', '2024-09-24 13:51:33', 0, 0),
(103, '9507d350e3d66cda33a0e32cf1924b58', 'שרון', 'הסמינר ממש חמוד - מדבר על יישומים של (בעיקר) רשתות נוירונים מכל מיני סוגים לבעיות בעולם הציפים והחמרה. מומלץ (אבל לא חובה) גם ידע בעמוקה', '2024-09-24 14:03:26', 0, 0),
(23, '9507d350e3d66cda33a0e32cf1924b58', 'אנונימי', 'חגית מרצה מדהימה באופן כללי ואז גם כיף ללמוד את החומר. הקורס עצמו גם מעניין, חשוב ומגניב. תבים קצת קשים אבל המתרגל (אלון) מעולה!', '2024-09-24 14:04:28', 1, 0),
(44, '9507d350e3d66cda33a0e32cf1924b58', 'אנונימי', 'אין ככ טעם להגיע להרצאות כי הן די חופרות והמתרגל חוזר על החומר וגם אשכרה עושה איתנו תרגילים. כן שווה לעשות ספידראן על המצגות אבל לא ממש מעבר', '2024-09-24 14:08:16', 0, 0),
(104, 'cb0acf7355db7b8ff5d0b19e76a1db37', 'ירדן', 'רפיק מרצה מעולה , מסודר , זמין מאוד לשאלות , סבלני לסטודנטים. מעביר את החומר בצורה ברורה מדוייקת ומעניינת. ', '2024-10-11 16:52:53', 1, 0),
(13, 'cb0acf7355db7b8ff5d0b19e76a1db37', 'ירדן', 'מעביר את החומר בצורה די משעממת. מסודר מאוד , בסיום הקורס אם תשקיעו תבינו את החומר בצורה טובה . מבחנים קשים לעומת מרצים אחרים , דורש פורמליות בכל תשובה.', '2024-10-11 16:54:04', 0, 0),
(12, 'cb0acf7355db7b8ff5d0b19e76a1db37', 'ירדן', 'אני נהנתי ללמוד אצל גיא , מעביר את החומר בצורה מעניינת וברורה , לפעמים קצת מפוזר. מבחנים הוגנים . דאג להקליט את כל השיעורים מה שסייע לסטודנטים במילואים. מרצה מעולה', '2024-10-11 16:55:23', 0, 0),
(105, 'cb0acf7355db7b8ff5d0b19e76a1db37', 'אנונימי', 'יעל מרצה מסודרת מאוד . מעבירה את החומר בצורה ברורה . הרצאות מעט משעממות וקשה להתרכז , אבל יש הקלטות ונוח לראות אותם בבית . המבחן היה פייר ותאם את רמת התרגילים שקיבלנו בעבודות הבית .', '2024-10-11 16:57:01', 0, 0),
(6, '1998baad2acdc0bc8f9c7e2ad7f98f47', 'אנונימי', 'יורי מרצה שמבין את החומר ברמה גבוהה, אבל מורה שקשה להבין את החומר בהרצאות שלו. המבחנים בדרך כלל מחולקים ל5 שאלות כשהראשונות פתירות ולא מאוד קשות (במיוחד עם חומר פתוח), והאחרונות קשות לפעמים לא פתירות. בהתאם לרמת מבחן ולאחוז נכשלים הדי גבוהה בדרך כלל יש פקטור. וגם הפקטור ניתן באלגוריתם (למשל ציון הבחינה עם פקטור היה הציון שהגעתם אליו ועוד השאלה עם הכי הרבה נק&#039;).', '2024-11-05 09:18:21', 0, 0),
(12, '96eb674c9400f5c14f29ca31305aef3a', 'אנונימי', 'המרצה הכי טוב בכל החוג', '2024-12-24 10:57:52', 0, 0),
(36, 'fb4099a2451348c720e02146e9402b2b', 'נגה', 'החומר מעניין מאוד, חלק מהנושאים רלוונטיים להרבה תחומים. הקורס הוא המשך של אלגוריתמים אבל הרבה יותר מפורט ועם מושגים חדשים. מורן מרצה מעולה. תרגילי הבית קשים, 3 שבועות לגליון. המבחן סביר מאוד והיה גם פקטור שהועיל למי שקיבל ציון טוב. הערה: מודלים חישוביים אינו קדם אבל מומלץ לקחת במקביל או לפני הקורס כי p,np מוזכרות בכל שיעור', '2025-02-18 12:54:36', 0, 0),
(109, '007e38c98ee5be3c972b7675a15be69c', 'אנונימי', 'מרצה מאוד נחמדה הרוב קיבלו 90+. הסמינר מועבר באנגלית והחומר לא מאוד קל אך ניתן להבנה. מכינים את המצגות לבד (שזה יותר עוזר בלהתאמן על החומר ועל מה רוצים לכלול בהגשה). מאוד ממליצה לקחת עם עדי סמינר', '2025-02-28 17:32:05', 1, 0),
(89, '0d2e46a6500a579840c6c81228f49c3c', 'אנונימי', 'הקורס באופן עקרוני מעניין אבל צריך להיות מאוד מרוכזים בהרצאות של ארז כי לפעמים הוא לא מסביר ישר נושאים המבחן טכני והוגן בסה&quot;כ.', '2025-03-03 22:11:40', 0, 0),
(110, '106b63d68e603107f36cc5e051632f30', 'אנונימי', 'שלי מאוד מסודרת ועונה על כל השאלות במודל, הקורס קל והמבחן מאוד הוגן. קשה להישאר מרוכז בהרצאות אבל אפשר להשלים הכל מהמצגות שבמודל ולהוציא ציון טוב.', '2025-03-18 18:26:10', 0, 0),
(112, '01ffec7fe6c63c1f906f3bdf6282e471', 'אנונימי', 'הקורס מועבר בצורה מאוד מעניינת ועמית גם מאוד מצחיק אז לא יהיה לכם משעמם בהרצאות, המבחן ברמה סבירה וגם בודק ברחמנות את המבחן. אפשר לסיים עם ציון גבוה בקורס.  ', '2025-03-26 08:56:46', 0, 0),
(44, '01ffec7fe6c63c1f906f3bdf6282e471', 'אנונימי', 'היו לי הרבה מרצים משעמים וסיימון הוא ברמה מעל כולם, המלצה שלי תלכו רק להרצאות הראשונות ואל תמשיכו כי גם ככה התרגולים עוברים על כל החומר ובמדיוק יותר. הבחינה הייתה מאוד קשה בשנה שאני עשיתי את הקורס איתו (בשני המועדים הייתה הארכה של 20 דקות בבחינה).', '2025-03-26 09:01:54', 0, 0),
(58, 'fb4099a2451348c720e02146e9402b2b', 'נגה', 'קורס מעניין, הרבה מושגים שלא לגמרי קשורים אחד לשני מלבד העובדה שכולם בתחום למידת מכונה. תרגילי הבית היו פשוטים יחסית ועזרו להבנה. המבחן תיאורטי מאוד, עמוס, כל החומר של הקורס מופיע בו בצורה כזו או אחרת. עם השקעה זה אחד הקורסים הכי שימושיים שתקחו בתואר', '2025-04-02 07:41:28', -1, 0),
(112, '76f9a51b5802972bf5223d2f5a5a8eac', 'אנונימי', 'לא תמצאו מרצה טוב יותר מעמית, הוא מרצה מצוין, ומסביר בצורה מהנה ודואג להכל גם המבחנים שלו מאוד הוגנים ', '2025-04-13 10:15:10', 0, 0),
(89, 'db16de2b39e07ac6d4f49e97b5199f42', 'ניב', 'הכל ברור מאוד, ממליץ ללמוד בעיקר מתרגולים למבחן, מבחן מאוד טכני צריך לענות מהר כדי להספיק לענות על הכל. שאלה של הוספת פקודה קצת צריך לחשוב.', '2025-04-21 12:02:29', 0, 0),
(113, 'cb0acf7355db7b8ff5d0b19e76a1db37', 'אנונימי', 'מרצה נחמדה והוגנת מאוד לסטודנטים , דואגת להקלטות איכותיות לסטודנטים', '2025-07-21 16:52:50', 0, 0),
(69, 'cb0acf7355db7b8ff5d0b19e76a1db37', 'אנונימי', 'רונן אחד מהמרצים הטובים בחוג . חריף , חד והופך את החומר למעניין , מבחן פייר ובדיקה הוגנת . הקורס עצמו מעניין בטירוף , ומשלב הרבה אלמנטים שנלמדו בשנתיים הראשונות , כיף לראות את הכול מתחבר ורונן דואג לכך בצורה טובה', '2025-07-21 16:54:22', 0, 0),
(114, '01ffec7fe6c63c1f906f3bdf6282e471', 'אנונימי', 'הקורס מאוד מעניין ועמית מרצה מדהים, תרגילי הבית בקורס מאתגרים מאוד ודורשים השקעה רצינית, אך מנגד הציונים בדרך כלל גבוהים. בנוסף, בסיום הקורס מתקיימת גם בחינה בעל־פה. עמית פרגן בציונים בסוף.', '2025-08-23 19:01:40', 0, 0),
(114, '9507d350e3d66cda33a0e32cf1924b58', 'אנונימי', 'אתם יכולים להשקיע כל הסמסטר בתרגילי בית ולקבל ציון טוב שיעזור לכם, אבל בסופו של דבר גם אם עניתם נכון בבוחן בעל פה הוא ייתן ציון לפי איך שהוא התרשם ממכם. נכון לכתיבת שורות אלה, גם אם אכפת לו, יש לו תחושת עילאיות פנימית כזאת.', '2025-08-23 22:29:05', 0, 0),
(115, '9507d350e3d66cda33a0e32cf1924b58', 'אנונימי', 'קורס מושלם וכיפי למי שאוהב אלגברה ב (פירוקים). הוא קצת חופר במקומות מסויימים טכניים ומשעממים אבל עדיין מלמד ואפשר בתוך שבועיים וקצת ללמוד את כל הקורס, לפתור את כל השאלות מהספר ולקבל בקלות ציון גבוה. ממליץ!', '2025-08-23 22:31:09', 0, 0),
(56, '25e70e5001fd86b0a28690c87ab743ec', 'אנונימי', 'פקטור מפנק', '2025-08-26 11:34:43', 0, 0),
(1, '25e70e5001fd86b0a28690c87ab743ec', 'אנונימי', 'לא מומלץ. היא ממש מורידה על כל מה שהוא לא פורמלי לדעתי באופן קצת מוגזם, אבל היא אישית נחמדה באישיות וההרצאות היו סך הכך בסדר.', '2025-09-08 12:50:52', 0, 0),
(58, '15356dbf6de81023d96da7ee2cb22d88', 'אנונימי', 'קורס קליל ונחמד, המרצה מציג את החומר בצורה נוחה ומובנת ,בקורס יש קצת מתמטיקה', '2025-09-13 09:45:50', 0, 0),
(115, '9507d350e3d66cda33a0e32cf1924b58', 'אנונימי', 'אם בא לכם מרצה שיכולה להפר את הסילבוס ושלא יהיה לה אכפת מזה - תיקחו', '2025-09-14 10:36:08', 0, 0),
(116, '0d26ca0f952f6564bd6506e0eeabc32b', 'אנונימי', 'זה קורס של 3 נ&quot;ז בקיץ, אבל בפועל האינטנסיביות והעומס הם של קורס עם הרבה יותר נ&quot;ז. הוא מתקיים יום שלם (כ-9 שעות): בבוקר תחרות תכנות, אחריה מעבר על הפתרונות, ואז שיעור עם חומר חדש לקראת התחרות הבאה. כל שבוע יש בערך 4-5 שאלות לתרגול בין התחרויות.  את השיעורים העבירו שני אתגריסטים שבאמת מבינים את החומר ומשקיעים מאוד - לפעמים קצת מבולבלים בהסבר, אבל תמיד נשארים עד הסוף ועוזרים. באמת כל הכבוד להם. אבל הציון בכלל נקבע על ידי מרצה שלא היה נוכח כמעט בכלל - הוא הגיע רק לשיעור הראשון ומאז נעלם. לא ניתנו קריטריונים ברורים לציון, לא הייתה שקיפות, ובסוף אף אחד לא באמת הבין על סמך מה נקבע הציון שלו. רק אחרי ערעורים נשלח הסבר חלקי ולא ברור על חישוב הציון.  בנוסף, בתחילת הקורס נאמר שהתחרויות יהיו אישיות רק בהתחלה ואחר כך בקבוצות, אך בפועל כל התחרויות נשארו אישיות. זה הפך את יום הלימודים לחוויה מתישה - לשבת 4 שעות לבד בתחרות שקטה פעם בשבוע באמצע סמסטר קיץ אינטנסיבי.  הקורס הוגדר כקורס למצטיינים, אבל בפועל הממוצע היה 83. במקום קורס שמעודד ומתגמל מצטיינים, הוא הפך לקורס שפשוט פוגע בממוצע של הסטודנטים החזקים באוניברסיטה. התחושה היא שמי שבא ללמוד ולהתקדם - נענש על כך.  לסיכום: למרות הכוונה הטובה, כרגע זה קורס שלא שווה את ההשקעה. עד שלא תהיה שיטת הערכה ברורה, שקיפות מלאה ומרצה שבאמת מעורב - עדיף לוותר. חבל שקורס למצטיינים מרגיש כמו מלכודת שמורידה ציונים במקום לקדם מצוינות.', '2025-11-04 17:16:35', 0, 0);

